def add(ident,choice,scope,approach,rows,synthesis,example):
    # All prose passed below is authored for this exact record; only serialization is automated.
    prev=original_by_id[ident].get('fields',original_by_id[ident]).get('market_comparisons',[])
    comparisons=[]
    for key,similar,different in rows:
        s=S[key]; old=[e for e in prev if document_key(e['source_url'])==document_key(s['source_url'])]
        refs=list(dict.fromkeys([r for e in old for r in e['source_refs']]+['U477']))
        comparisons.append({k:s[k] for k in ('vendor','product','source_title','source_url','source_version','source_locator','consulted_on','concept_name','scope_summary','approach_summary','evidence_limits')} | dict(element_name=s['concept_name'],element_type='Concept documenté par la source primaire',relationship='Recouvrement partiel',similarities=similar,differences=different,flow_position=choice,status=old[0]['status'] if old else 'proposed',source_refs=refs))
    key,title,situation,outcome,lesson=example
    s=S[key]
    ex=dict(title=title,situation=situation,outcome=outcome,lesson=lesson,source_title=s['source_title'],source_url=s['source_url'],source_refs=['U477'])
    EXAMPLES.setdefault(key,[]).append(dict(target=ident,title=title,attribution='Illustration FLOW' if 'Illustration FLOW' in title or 'Illustration FLOW' in situation else 'Exemple de la source',situation=situation))
    profile=dict(choice=choice,flow_scope=scope,flow_approach=approach,synthesis=synthesis,examples=[ex])
    assert ident not in OUT, ident
    OUT[ident]=dict(id=ident,market_comparisons=comparisons,market_inspiration=profile)

add('D01', 'Connaître les marchandises présentes ou attendues et préserver leurs usages : Inventory Management réunit la fiabilité du stock, ses mouvements, protections et réservations. Le choix du stock souhaitable reste dans Inventory Optimization.',
    'Connaissance, fiabilité et usages du stock.', 'Tenir une situation expliquée et appliquer les engagements autorisés.',
    [('sapinv','Quantités, propriété et états sont suivis ensemble.','SAP inclut la valorisation financière ; FLOW ne l’absorbe pas.'),('onhand','Présent, réservé et attendu restent distingués.','Une vue produit ne représente pas tout le domaine FLOW, notamment sa gouvernance des protections.')],
    ['SAP donne à Inventory Management un périmètre incluant la valorisation ; Microsoft montre comment lire et expliquer les quantités. Ces deux éclairages soutiennent un domaine qui sait à la fois connaître le stock et en préserver les usages.', 'FLOW sépare le stock connu du stock souhaitable : ce dernier relève de D05. Réserver ne déplace pas les marchandises et un approvisionnement attendu ne devient pas du stock présent.'],
    ('consign','Exemple Microsoft — reçu mais encore fournisseur','Chez USMF, une matière consignée arrive avant son utilisation en production.','La réception est enregistrée sans transfert immédiat de propriété.','Le domaine doit connaître les biens détenus et leur propriétaire avant d’appliquer les suites prévues par l’accord.'))

add('D01.f','Savoir combien de pièces sont présentes et dans quel état : Inventory Tracking tient cette situation à partir des faits reconnus. Les ressources attendues restent identifiées séparément.',
    'Quantités et états par produit, lieu et propriété utile.', 'Actualiser la situation sans compter deux fois le même fait.',
    [('journals','Les faits de réception, sortie et correction expliquent les quantités.','Le journal Microsoft inclut des effets comptables ; FLOW sépare conservation des faits et établissement des quantités.'),('onhand','La situation distingue présent, réservé et attendu.','La liste Microsoft expose aussi des calculs de disponibilité ; Tracking fournit d’abord la situation de référence.')],
    ['Microsoft documente deux faces complémentaires : les journaux portent les variations, la liste de stock en restitue le résultat. FLOW distingue explicitement l’enregistrement des faits et le maintien des quantités.', 'Le nom Tracking exprime cette continuité. Une réservation peut changer l’état logique sans sortie physique ; les futurs apports ne sont pas additionnés au présent.'],
    ('journals','Illustration FLOW — une réception corrigée','Une réception déclarée à 100 pièces est corrigée à 80.','La situation retenue est 80 présentes ; les deux déclarations ne font pas deux réceptions.','Tracking établit la bonne quantité ; Record Inventory Movements conserve l’explication de la correction.'))

add('D01.g','Expliquer pourquoi le stock a changé : Record Inventory Movements conserve les mouvements reconnus et leurs corrections. Le fait reste distinct du document qui le décrit.',
    'Réceptions, sorties, transferts et changements d’état ou de propriété.', 'Conserver une trace justifiée, datée et corrigeable.',
    [('consign','Un changement de propriété peut être enregistré sans déplacement.','Le journal d’acquisition Microsoft porte aussi des suites d’achat et financières.'),('epcis','Un fait et sa correction gardent leurs dates et leur contexte.','EPCIS définit des événements de visibilité, pas le registre FLOW ni son mode de stockage.')],
    ['Microsoft illustre un mouvement sans déplacement : l’acquisition de marchandises consignées. GS1 éclaire la trace du fait et la manière de signaler une erreur sans rendre le passé illisible.', 'FLOW retient le service d’enregistrement et d’explication. Calculer la nouvelle quantité appartient à Inventory Tracking ; une architecture de journal technique n’est pas prescrite.'],
    ('epcis','Exemple GS1 — compléter une expédition déclarée','Le guide décrit trois produits déclarés expédiés, alors qu’un quatrième est aussi parti.','Un fait complémentaire permet de reconnaître le quatrième produit.','Une correction explique la variation ; elle ne doit pas effacer la distinction entre ce qui s’est passé et ce qui était connu.'))

add('D01.c','Voir une situation de stock compréhensible dans les différents lieux : Inventory Visibility rapproche les quantités présentes, leurs états et les ressources attendues. La vue indique ce qu’elle sait, sans inventer une disponibilité garantie.',
    'Lecture cohérente du présent et de l’attendu.', 'Restituer les quantités avec leur périmètre et leur fraîcheur.',
    [('onhand','Les dimensions rendent le résultat compréhensible par lieu et produit.','Une liste dans un ERP ne règle pas à elle seule la cohérence entre tous les systèmes.'),('supply','Le bilan sépare quantité actuelle et apports à venir.','Oracle propose ses propres règles de disponibilité ; FLOW ne les impose pas à toute lecture.')],
    ['Microsoft insiste sur les dimensions de lecture ; Oracle ajoute une chronologie des entrées et des besoins. Les deux rendent visible un stock expliqué plutôt qu’un total isolé.', 'FLOW applique cette exigence aux différents périmètres. La vue de stock alimente la promesse mais ne prend pas à sa place l’engagement d’une quantité à une date.'],
    ('onhand','Illustration FLOW — total et détail','Deux magasins détiennent 15 et 25 pièces d’une référence.','La lecture réseau donne 40 ; le détail permet de retrouver les deux lieux.','Une seconde copie de ces informations n’ajoute pas 40 pièces au réseau.'))

add('D01.d','Fiabiliser le stock en confrontant les quantités enregistrées à des comptages : Stocktaking qualifie les écarts et les corrections justifiées. Les constats physiques sont réalisés par les exécutants.',
    'Campagnes complètes, contrôles tournants et vérifications ciblées.', 'Rapprocher le constat et l’enregistrement avant correction.',
    [('physical','Inventaire complet et comptage tournant vérifient les quantités.','Oracle impose des règles opératoires de son application ; FLOW n’impose pas l’arrêt systématique des mouvements.'),('cycle','Le résultat compté peut nécessiter une revue des écarts.','Les écrans et tâches d’entrepôt Microsoft ne deviennent pas des comportements supplémentaires.')],
    ['Oracle distingue campagne complète et vérifications successives ; Microsoft précise les contrôles tournants et ponctuels. Ces méthodes ont la même finalité de fiabilité mais des rythmes différents.', 'FLOW emploie Stocktaking pour les réunir et garder communs le rapprochement et la justification. Un écart de comptage ne vaut pas correction automatique.'],
    ('cycle','Exemple Microsoft — contrôle d’un écart','La quantité enregistrée est 50 et la tolérance de l’opérateur est de 10.','Un résultat hors de l’intervalle 40–60 demande une revue.','Les seuils peuvent organiser la revue ; le modèle ne reprend pas ces valeurs comme règles métier.'))

add('BHV029','Établir une référence fiable sur tout un périmètre : Periodic Physical Inventory décrit une campagne complète de comptage. Sa fréquence et le traitement des mouvements sont explicités pour chaque campagne.',
    'Ensemble des stocks d’un magasin, entrepôt ou périmètre défini.', 'Comparer le constat global à une référence datée.',
    [('physical','Physical Inventory rapproche le stock complet des quantités comptées.','L’interdiction de mouvements décrite par Oracle est propre à son parcours, pas une obligation FLOW.'),('journals','Les journaux de comptage permettent de justifier les écarts.','Microsoft ne définit pas à lui seul la couverture complète ni la fréquence de la campagne.')],
    ['Oracle donne le nom et le principe de l’inventaire complet ; Microsoft détaille le traitement de ses résultats. Les deux soutiennent la fiabilisation, à des mailles différentes.', 'FLOW retient la campagne exhaustive sur un périmètre choisi. « Periodic » ne signifie pas nécessairement annuel et ne rend pas cette méthode exclusive du comptage tournant.'],
    ('physical','Illustration FLOW — inventorier un magasin','Une campagne couvre toutes les références d’un magasin à une date donnée.','Les constats sont rapprochés de la situation enregistrée au même repère temporel.','Les ventes ou réceptions autour du comptage doivent être expliquées avant de conclure à un écart.'))

add('BHV030','Entretenir la fiabilité sans attendre une campagne complète : Cycle Counting organise des vérifications récurrentes de sélections de stock. Le rythme dépend des enjeux de chaque sélection.',
    'Articles ou emplacements contrôlés régulièrement.', 'Choisir fréquence et déclencheurs utiles au contrôle.',
    [('cycle','Des plans ou seuils organisent les contrôles récurrents.','Un seuil de comptage n’est pas un seuil de réapprovisionnement.'),('physical','Oracle décrit un comptage d’articles réparti sur l’année.','La classification ABC ou les terminaux ne sont pas obligatoires dans FLOW.')],
    ['Microsoft décrit des plans et des déclencheurs ; Oracle oppose les comptages successifs à l’inventaire complet. Le vocabulaire Cycle Counting est commun à ces usages proches.', 'FLOW conserve cette méthode de contrôle sans imposer une classification ni un calendrier unique. Les écarts restent instruits dans Stocktaking.'],
    ('cycle','Exemple Microsoft — compter après un prélèvement','Un emplacement contient 60 pièces et son seuil de contrôle est fixé à 40.','Après prélèvement de 25 pièces, il en reste 35 : un comptage est créé.','La quantité faible facilite un contrôle ; elle ne prouve pas une erreur et ne déclenche pas nécessairement un réassort.'))

add('BHV031','Lever rapidement un doute sur un stock ciblé : Spot Counting permet une vérification ponctuelle sans attendre le prochain contrôle récurrent. La demande de contrôle ne présume pas le résultat.',
    'Vérification d’un article ou emplacement motivée par une situation.', 'Recevoir le constat puis examiner l’écart éventuel.',
    [('cycle','Le spot cycle count peut démarrer sans tâche préexistante.','FLOW décrit le besoin de contrôle ponctuel, au-delà de la modalité mobile Microsoft.'),('spot','Oracle propose un contrôle non planifié pendant un prélèvement.','Son déclenchement par faible reliquat est un cas particulier, pas tout Spot Counting.')],
    ['Microsoft permet un contrôle ponctuel à l’initiative de l’opérateur ; Oracle propose de profiter d’un prélèvement laissant peu de pièces. Les déclencheurs diffèrent mais évitent d’attendre une campagne.', 'FLOW retient Spot Counting pour le besoin de vérification ciblée. Ni anomalie certaine ni autorisation de corriger ne résultent de son seul déclenchement.'],
    ('spot','Exemple Oracle — compter les cinq dernières pièces','Le seuil opportuniste est de cinq pièces et un prélèvement laisse cinq pièces ou moins.','Oracle propose de compter ; un contrôle récent peut éviter de répéter la demande.','C’est une façon documentée de cibler un contrôle, pas une règle universelle de comptage.'))

add('D01.h','Appliquer les conditions du stock appartenant encore au fournisseur : Consigned Inventory Management distingue détention, utilisation et acquisition. Les issues possibles dépendent de l’accord de consignation.',
    'Propriété, droits d’usage, échéances et sorties autorisées.', 'Appliquer le régime puis mobiliser achats, retours et prestations utiles.',
    [('consign','La réception ne transfère pas la propriété ; l’utilisation peut le faire.','Le scénario Microsoft est celui de matières de production, pas toutes les consignations retail.'),('aging','La durée contractuelle peut déclencher l’acquisition.','L’échéance Oracle est une clause possible, pas un achat automatique universel.')],
    ['Microsoft illustre l’acquisition liée à l’utilisation ; Oracle montre celle liée au temps. La propriété fournisseur est leur point commun, les déclencheurs sont différents.', 'FLOW réunit l’application de ces conditions sans décider implicitement d’acheter tous les invendus. Les commandes et la réalisation des retours restent portées par leurs responsables.'],
    ('consign','Exemple Microsoft — matière fournisseur dans l’usine','USMF reçoit puis conserve de la matière appartenant au fournisseur.','La propriété des quantités destinées à la production change avant leur consommation.','Détention et propriété doivent rester visibles séparément ; le mécanisme est adapté à l’accord applicable.'))

add('BHV063','Acquérir les quantités lorsqu’elles sont utilisées selon l’accord : Consumption-Based Ownership Transfer applique ce déclencheur de propriété. Le stock restant peut continuer à appartenir au fournisseur.',
    'Quantités dont la vente ou consommation déclenche l’acquisition.', 'Reconnaître l’événement convenu et ses effets de propriété.',
    [('consign','L’utilisation en production déclenche le changement de propriétaire.','Cette séquence de fabrication ne signifie pas que toute vente retail déclenche automatiquement un achat.'),('consume','Oracle distingue consommation et changement de propriété.','Les écritures d’achat et de règlement dépassent ce comportement FLOW.')],
    ['Microsoft et Oracle relient la consommation convenue à l’acquisition de stock consigné. Les deux décrivent aussi les documents financiers, qui restent distincts dans FLOW.', 'Le nom précise le déclencheur : l’utilisation. Une acquisition fondée sur l’ancienneté relève du comportement voisin et ne prouve aucune sortie physique.'],
    ('consign','Illustration FLOW — seules vingt pièces sont acquises','Sur cent pièces consignées, vingt sont vendues dans un accord qui lie vente et acquisition.','Ces vingt changent de propriétaire ; quatre-vingts restent consignées.','Le fait de vente et la clause doivent être établis avant d’appliquer le transfert de propriété.'))

add('BHV064','Appliquer une obligation d’acquisition lorsque la durée convenue est atteinte : Aging-Based Ownership Transfer rend ce déclencheur explicite. Il dépend du contrat, pas d’une règle générale sur les invendus.',
    'Stock consigné arrivé à l’échéance d’acquisition.', 'Identifier les quantités échues et appliquer la clause.',
    [('aging','Oracle Cloud relie ancienneté convenue et transfert de propriété.','La page prévoit une opération de transfert ; elle n’établit pas un automatisme obligatoire.'),('consume','Oracle EBS décrit l’achat de stock non consommé à échéance.','Deux versions Oracle documentent le mécanisme, sans prouver un consensus de tous les éditeurs.')],
    ['Oracle Cloud et EBS décrivent le même motif : une durée contractuelle peut rendre le stock acquérable sans consommation préalable. Cloud insiste sur l’opération de transfert ; EBS sur le repérage des quantités échues.', 'FLOW reprend ce mécanisme sous un nom explicite. Détenir une pièce depuis longtemps ne suffit pas : la clause et son point de départ doivent être connus.'],
    ('aging','Illustration FLOW — acquisition à quatre-vingt-dix jours','Un accord prévoit d’acquérir les pièces encore présentes après 90 jours.','Les quantités concernées changent de propriétaire à l’échéance applicable.','Ces valeurs illustrent un contrat possible ; elles ne décrivent aucune règle Beaumanoir.'))

add('BHV065','Donner suite à une sortie autorisée de consignation : Consignment Exit applique le devenir retenu et mobilise les commandes et prestations nécessaires. Il ne choisit pas seul la filière ni ne suppose une acquisition préalable.',
    'Reprise fournisseur ou autre issue autorisée par l’accord.', 'Faire respecter propriété et conditions de sortie.',
    [('consreturn','Le retour dépend notamment de l’état de propriété.','Oracle documente des retours, pas toutes les filières envisagées par FLOW.'),('dispo','Réparation, renvoi, seconde vie et destruction sont des orientations distinctes.','Microsoft parle de produits retournés en général ; la consignation ajoute l’accord du propriétaire.')],
    ['Oracle traite précisément le retour consigné ; Microsoft illustre la variété des devenirs possibles d’un produit. Une orientation logistique ne dispense pas de vérifier qui peut l’autoriser.', 'FLOW conserve les autres filières comme issues conditionnelles prévues par son modèle, pas comme fonctions Oracle démontrées. Choisir l’issue et l’exécuter restent séparés.'],
    ('consreturn','Illustration FLOW — reliquat repris','Le fournisseur autorise la reprise de trente pièces encore consignées.','La sortie mobilise le retour fournisseur et les prestations convenues.','Aucun achat fictif n’est créé pour rendre la sortie possible ; les règles de propriété restent explicites.'))

add('D02.b','Préserver les usages du stock et encadrer son renouvellement : Supply Protection met en vigueur les droits, limites et règles retenus. Décider leurs valeurs et les appliquer sont des responsabilités distinctes.',
    'Enveloppes, plafonds, sécurité et règles de réassort.', 'Maintenir des conditions d’usage cohérentes et explicites.',
    [('alloc','Des enveloppes protègent les groupes et suivent leur consommation.','Inventory allocation ne couvre pas toute la politique de renouvellement FLOW.'),('safety','Le tampon et son droit d’utilisation sont explicités.','La sécurité n’est ni une réservation individuelle ni une enveloppe de canal.'),('coverage','Les seuils et modes encadrent le réassort.','Microsoft regroupe configuration et calcul ; FLOW garde la décision d’apport distincte.')],
    ['Microsoft documente plusieurs moyens de protéger les usages : enveloppes de groupe, sécurité et règles de couverture. Ils ne répondent pas à la même question : qui peut utiliser, quelle marge conserver, quand renouveler.', 'FLOW les rapproche dans Supply Protection pour maintenir des règles cohérentes. Les décisions spécialisées en déterminent les valeurs ; leur mise en vigueur ne déplace aucune marchandise.'],
    ('alloc','Exemple Microsoft — vélos rares chez Contoso','Contoso doit préserver des vélos pour ses canaux et partenaires pendant une perturbation d’approvisionnement.','Des quantités sont attribuées à des groupes avant les commandes finales.','La protection porte sur des droits de groupe, distincts d’une réservation pour une commande nommée.'))

add('D05.d','Choisir combien préserver pour chaque groupe et quelles limites lui imposer : Group Protection Decision arbitre ces quantités selon les besoins et priorités. Les droits retenus sont ensuite appliqués par Supply Protection.',
    'Quantités protégées et limites par canal ou population.', 'Comparer les besoins concurrents et expliquer le partage.',
    [('alloc','L’enveloppe organise le partage entre groupes.','Microsoft décrit aussi l’application et la consommation ; FLOW isole ici le choix des quantités.'),('pal','Les plafonds de groupe bornent les confirmations.','PAL ne garantit pas que la quantité plafonnée restera disponible pour le groupe.')],
    ['Microsoft met en avant une enveloppe préservée ; SAP PAL limite ce qu’un groupe peut consommer. Ces leviers se ressemblent dans leurs nombres mais diffèrent dans leur garantie.', 'FLOW décide séparément ce qui doit être protégé et ce qui ne doit pas être dépassé. Le mot Allocation des éditeurs ne vaut donc pas une unique responsabilité FLOW.'],
    ('pal','Exemple SAP — un plafond sans garantie','SAP limite certains grossistes à 200 unités au nord et 100 au sud sur un stock de 500.','Une autre demande non limitée peut néanmoins consommer le stock avant eux.','Choisir un plafond ne suffit pas à préserver une quantité pour un groupe qui commande plus tard.'))

add('BHV017','Préserver l’accès d’un groupe avant que ses demandes arrivent : Group Supply Protection applique les droits qui empêchent d’autres usages d’épuiser son enveloppe. Les quantités à protéger sont décidées ailleurs.',
    'Accès préservé par groupe et conditions d’usage.', 'Appliquer une protection mutuelle ou priorisée.',
    [('alloc','Le ring fencing vise explicitement des quantités préservées.','Les groupes Microsoft sont une réalisation possible, pas une hiérarchie imposée.'),('pal','PAL peut contribuer à répartir l’accès entre groupes.','Un plafond isolé n’est pas une garantie, surtout si d’autres demandes restent sans limite.')],
    ['Microsoft décrit directement la préservation d’une enveloppe. SAP montre pourquoi limiter certaines demandes ne protège pas automatiquement toutes les autres.', 'FLOW nomme le bénéfice recherché : garder un accès possible au groupe protégé. Il faut expliciter les usages concurrents et les conditions, sans promettre une disponibilité absolue.'],
    ('alloc','Illustration FLOW — attendre la demande du web','Deux cents pièces sont préservées pour un canal dont les commandes arriveront plus tard.','Les autres groupes ne peuvent pas consommer cette enveloppe selon la règle applicable.','Cette protection précède les commandes individuelles et n’est pas encore leur réservation.'))

add('BHV018','Empêcher un groupe de consommer au-delà de sa limite : Consumption Capping maintient un plafond sur un périmètre et une période. Un maximum autorisé n’assure pas un minimum disponible.',
    'Limites de consommation cumulée des groupes.', 'Suivre ce qui reste autorisé après chaque utilisation.',
    [('pal','Les quantités PAL bornent ce qui peut être confirmé.','Le contrôle SAP intervient dans ses mécanismes ATP et Supply Assignment.'),('alloc','L’oversell control limite la consommation d’une enveloppe.','Microsoft l’associe au ring fencing ; FLOW distingue plafonner et protéger.')],
    ['SAP PAL exprime directement une limite de confirmation ; Microsoft associe une limite de consommation à ses allocations. Les deux contrôlent le dépassement.', 'FLOW sépare ce résultat d’un droit préservé. Un groupe peut avoir encore un droit théorique sans trouver suffisamment de stock admissible.'],
    ('pal','Illustration FLOW — maximum de cinq cents','Un groupe a déjà consommé 480 unités sur un plafond de 500 pour la période.','Une nouvelle demande de 40 ne dispose que de 20 unités de marge sur ce plafond.','Le contrôle du plafond s’ajoute au contrôle des ressources réellement disponibles.'))

add('BHV019','Définir comment utiliser le stock tampon : Safety Stock Policy maintient les conditions qui permettent d’absorber les aléas. Le niveau à retenir est déterminé par Inventory Target Decision.',
    'Rôle, droit d’usage et reconstitution du tampon.', 'Éviter de confondre sécurité, réservation et seuil de commande.',
    [('safety','La sécurité peut être mobilisée pour la demande puis reconstituée.','Les règles strictes ou souples de Microsoft ne sont pas un choix FLOW implicite.'),('policies','Oracle intègre la sécurité aux seuils de réapprovisionnement.','Additionner de nouveau ce tampon ferait compter deux fois la même protection.')],
    ['Microsoft explique si la sécurité peut servir un besoin réel ; Oracle montre sa contribution au calcul d’un seuil. Usage du tampon et déclenchement du réassort se complètent sans être identiques.', 'FLOW conserve une politique explicite : quand consommer cette marge et comment la rétablir. Le comportement applique les paramètres retenus, sans recalculer leur niveau optimal.'],
    ('safety','Illustration FLOW — utiliser la sécurité','Un besoin urgent arrive alors qu’il ne reste que le tampon de sécurité.','La règle autorise son utilisation et demande de prévoir sa reconstitution.','Un stock de sécurité n’est pas nécessairement intouchable ; sa disponibilité dépend de la politique.'))

add('BHV020','Encadrer quand et jusqu’où renouveler le stock : Replenishment Regulation maintient les seuils, cibles et règles de déclenchement retenus. Le calcul des apports reste dans Replenishment Decision.',
    'Règles de réassort par lieu, produit et période.', 'Faire appliquer des paramètres cohérents de renouvellement.',
    [('coverage','Les modes par besoin, période ou min/max structurent le réassort.','Ces modes ne deviennent pas autant de sous-comportements FLOW.'),('policies','Oracle distingue cycle fixe, point de commande et cible.','Ses formules de calcul ne transfèrent pas la décision de niveau à cette gestion des règles.')],
    ['Microsoft classe les méthodes de réassort ; Oracle explicite leurs paramètres et leur utilisation. Les deux montrent qu’un seuil de déclenchement et une cible à atteindre sont différents.', 'FLOW conserve Replenishment Regulation pour tenir ces règles en vigueur. Une modification autorisée de cible n’est pas encore une modification de commande.'],
    ('coverage','Illustration FLOW — sous soixante, viser cent','La règle prévoit de déclencher un réassort sous 60 pièces pour viser 100.','Supply Protection maintient ces paramètres ; la décision de réassort les utilise avec les apports attendus.','La règle encadre le calcul sans créer elle-même un achat ni un transfert.'))

add('D02.c','Sécuriser une quantité pour une demande identifiée : Reservation établit un engagement dont les autres demandes doivent tenir compte. L’engagement ne signifie ni sortie physique ni déplacement de pièces.',
    'Création, maintien et révision des engagements de quantité.', 'Protéger le besoin selon les conditions accordées.',
    [('soft','La réservation réduit le disponible sans changer le stock physique.','Le service Microsoft est une mise en œuvre multicanal, pas le périmètre entier de la capacité.'),('orres','La quantité est liée à une demande et une ressource.','Oracle peut préciser lot ou emplacement ; FLOW ne l’exige pas pour tout engagement.')],
    ['Microsoft souligne l’effet sur le disponible partagé ; Oracle explicite le lien entre demande et ressource, présente ou attendue. Ces présentations convergent sur l’engagement quantitatif.', 'FLOW distingue Reservation de Supply Assignment : un simple lien d’affectation ne bloque pas les usages concurrents. Les conditions de libération ou révision doivent être explicites.'],
    ('soft','Exemple Microsoft — deux canaux voient différemment le stock','Le système de gestion affiche encore 100 pièces, mais une commande web en a déjà réservé dix.','Le service partagé ne présente que 90 comme réservables.','L’écart exprime un engagement ; il ne signifie pas que dix pièces ont déjà quitté l’entrepôt.'))

add('D05.h','Choisir quand et combien de temps sécuriser une demande : Reservation Policy Decision équilibre la garantie accordée et l’indisponibilité créée pour les autres ventes. Elle détermine une politique sans établir elle-même les réservations.',
    'Jalon, horizon, durée et conditions de maintien.', 'Arbitrer selon le service promis, la rareté et l’immobilisation.',
    [('ct','Plusieurs jalons et durées de réservation sont possibles.','Les modes produit ne déterminent pas automatiquement le meilleur compromis métier.'),('time','Une fenêtre peut différer la réservation jusqu’à proximité du besoin.','L’horizon avant besoin est différent de la durée d’une réservation déjà prise.'),('reserve','La politique peut varier selon le parcours et les besoins prioritaires.','Prioriser des commandes et choisir un régime de réservation restent deux décisions FLOW.')],
    ['commercetools compare panier et commande ; Oracle fournit un horizon avant expédition ; Microsoft illustre des motifs et stades de réservation. Les sources éclairent des dimensions complémentaires, pas une politique universelle.', 'FLOW regroupe leur choix dans une décision de stock. Reservation applique les engagements ; le propriétaire de la gouvernance des politiques reste à préciser dans le modèle.'],
    ('ct','Illustration FLOW — préserver une capsule sans la bloquer','Une capsule suscite des demandes rapides mais aussi des paniers abandonnés.','Le métier compare une réservation au panier courte et une réservation plus tardive.','La rareté ne dicte pas seule la réponse : le coût d’immobilisation et la garantie attendue sont comparés.'))

add('BHV032','Faire commencer la garantie au bon moment du parcours : Milestone-Based Reservation Policy choisit le jalon qui déclenche la réservation et ses conditions de continuité. Panier, paiement et commande sont des options, pas trois comportements.',
    'Événement déclencheur et maintien lors du passage à la commande.', 'Aligner la garantie réelle avec l’engagement annoncé au client.',
    [('ct','La réservation peut débuter au panier ou à la commande.','Ces modes de commerce ne couvrent pas tous les jalons métier FLOW.'),('shopify','Shopify retient le stock à la soumission du paiement.','Ce choix produit n’impose pas le même jalon à tous les parcours.')],
    ['commercetools offre des modes au panier et à la commande ; Shopify documente la retenue au paiement. Les produits rendent donc visibles des choix différents sur le même problème.', 'FLOW nomme la décision sur le jalon et la continuité de garantie. Le parcours mobilise cette politique ; le comportement ne conduit pas lui-même le paiement.'],
    ('shopify','Exemple Shopify — la retenue commence au paiement','Le client peut parcourir son panier avant de soumettre les informations de paiement.','Shopify retient alors le stock ; si le paiement échoue, la retenue est levée.','Un contrôle de disponibilité à une étape précédente ne signifiait pas encore que la pièce était réservée.'))

add('BHV033','Réserver assez près de l’échéance pour conserver de la souplesse : Time-Fenced Reservation Policy choisit la fenêtre avant le besoin. Cette fenêtre ne remplace pas le calcul d’une date réalisable.',
    'Horizon avant besoin et réexamen d’un changement de date.', 'Sécuriser progressivement les demandes futures.',
    [('time','Reservation Time Fence est un mécanisme nommé chez Oracle EBS.','La valeur choisie reste une décision métier ; la page ne donne pas un horizon optimal.'),('ps','PeopleSoft limite les réservations aux dates dans les lead days.','La même famille Oracle fournit deux réalisations, pas un consensus universel.')],
    ['Oracle EBS parle de Reservation Time Fence ; PeopleSoft de reservation lead days. Les deux font dépendre l’éligibilité de la distance à l’échéance.', 'FLOW conserve cette fenêtre distincte du délai d’expiration. Une demande lointaine continue à peser sur la promesse même si elle n’est pas encore réservée.'],
    ('time','Exemple Oracle — départ dans six jours','L’expédition est prévue dans six jours.','Une fenêtre de dix jours permet la réservation automatique ; une fenêtre de deux jours ne la déclenche pas encore.','Le nombre de jours est un choix de sécurisation, pas une nouvelle date promise.'))

add('BHV034','Adapter la garantie au service convenu pour la demande : Demand-Differentiated Reservation Policy définit des régimes distincts quand les engagements métier le justifient. Elle ne classe pas les commandes gagnantes.',
    'Conditions de réservation selon les engagements de service.', 'Différencier jalons et durées avec des raisons explicites.',
    [('reserve','Microsoft cite des besoins de réservation liés aux clients et types de commandes.','La priorité mentionnée par l’éditeur ne doit pas absorber Order Prioritization.'),('ps','Les règles de ligne et de commande modifient le traitement de la réservation.','Les critères PeopleSoft sont des exemples de réalisation, pas un régime FLOW prédéfini.')],
    ['Microsoft explique pourquoi certains engagements appellent une réservation différente ; PeopleSoft permet des conditions de traitement par contexte. L’un éclaire le motif, l’autre des règles applicables.', 'FLOW retient la différence de service effectivement promise. Une enveloppe protégée pour un groupe reste distincte de la politique appliquée à sa demande individuelle.'],
    ('reserve','Illustration FLOW — deux engagements de service','Un accord professionnel prévoit une mise de côté dès acceptation ; le web standard réserve au paiement.','Les deux demandes suivent des jalons de réservation différents.','La différence vient du service convenu, sans transformer automatiquement le professionnel en priorité absolue.'))

add('BHV035','Réexaminer la politique de réservation quand le risque change : Risk-Adaptive Reservation Policy peut recommander un autre jalon ou une autre durée. Les garanties déjà accordées restent soumises à leurs conditions.',
    'Adaptation aux tensions, à la fiabilité des apports et aux immobilisations.', 'Expliquer pourquoi maintenir ou modifier la politique.',
    [('ct','Jalon et expiration constituent des leviers de réglage.','La documentation ne démontre pas un moteur qui optimise ces réglages selon le risque.'),('ps','PeopleSoft décrit un traitement particulier des stocks rares.','Le pilotage manuel des pénuries ne prouve pas un apprentissage automatique de la politique.')],
    ['commercetools expose des leviers de jalon et de durée ; PeopleSoft permet un contrôle particulier en pénurie. Leur rapprochement donne des moyens d’adaptation, pas la preuve d’un moteur standard portant ce nom.', 'FLOW formule la responsabilité de choisir selon le contexte. Une tension peut justifier une garantie plus précoce, mais des abandons élevés peuvent au contraire rendre cette immobilisation nuisible.'],
    ('ct','Illustration FLOW — huit pièces et des paniers abandonnés','Huit pièces restent disponibles pendant que les demandes accélèrent.','Le métier compare une protection courte plus précoce avec un déclenchement plus tardif si les paniers sont souvent abandonnés.','L’adaptation a une justification et un horizon ; elle ne révoque pas silencieusement les réservations existantes.'))

add('D05','Choisir le stock souhaitable et les ajustements nécessaires : Inventory Optimization recherche un compromis entre disponibilité, immobilisation et risque. Les calculs éclairent les décisions sans rendre les marchandises physiquement disponibles.',
    'Objectifs de stock, protections et ajustements dans le réseau.', 'Comparer des résultats métier et préparer un scénario cohérent.',
    [('relex','Le stock est positionné pour répondre à la demande sans excès inutile.','RELEX décrit une offre plus large, avec prévision et mise en action intégrées.'),('science','La recherche relie niveau de service et coût du stock dans le réseau.','Ce modèle scientifique étudie surtout les stocks de sécurité ; FLOW inclut plusieurs décisions d’ajustement.')],
    ['RELEX emploie Inventory Optimization pour une démarche large de positionnement ; Achkar et ses coauteurs formalisent un problème plus précis de sécurité dans plusieurs échelons. Tous deux mettent en regard service et stock immobilisé.', 'FLOW conserve ce nom à la maille du domaine et explicite les responsabilités de décision. Ses objectifs peuvent être multiples ; aucune pondération ni minimisation monétaire unique n’est imposée.'],
    ('relex','Exemple pédagogique RELEX — les marges s’additionnent','Tori optimise séparément les stocks des centres et magasins.','L’article explique que des marges locales peuvent couvrir plusieurs fois le même risque.','Un meilleur compromis se cherche dans le réseau ; cela ne garantit pas une baisse de stock dans chaque lieu.'))

add('D05.a','Choisir combien de stock viser et quels seuils retenir : Inventory Target Decision détermine les objectifs par produit, lieu et période. Une cible est un résultat de décision, pas une commande de réassort.',
    'Objectifs et seuils de stock selon service, délais et risques.', 'Arbitrer la couverture souhaitable avant de déterminer les apports.',
    [('targets','Le calcul produit une proposition de minimum à examiner.','Le minimum Microsoft n’est pas toujours une cible complète de position de stock.'),('policies','Oracle calcule des paramètres de stock par produit et lieu.','La page couvre aussi les règles de commande, séparées dans FLOW.')],
    ['Microsoft distingue proposition de minimum et application ; Oracle relie minimum, sécurité et cible aux méthodes de réassort. Les nombres servent des rôles différents et doivent être nommés.', 'FLOW choisit Inventory Target Decision pour réunir la détermination des objectifs et seuils. Leur maintien relève de Supply Protection ; les apports sont décidés par les capacités de réapprovisionnement.'],
    ('targets','Illustration FLOW — objectif révisé avant application','Le service recherché augmente et le délai fournisseur devient moins fiable.','Une nouvelle cible est comparée à la précédente, avec ses conséquences sur le stock immobilisé.','Retenir la cible ne signifie pas qu’elle est déjà appliquée ni que les achats correspondants sont passés.'))

add('BHV026','Choisir un stock utile au magasin sans encombrer sa réserve : Store Inventory Optimization détermine ses cibles et seuils locaux. L’assortiment et la présentation souhaités constituent des entrées.',
    'Objectifs par produit, magasin et période.', 'Concilier demande locale, place, service et rythme de livraison.',
    [('auto','RELEX tient compte de la place en rayon et du réapprovisionnement magasin.','Son offre calcule aussi les apports ; FLOW isole ici les cibles.'),('targets','Microsoft calcule des minima selon produit et dimensions de couverture.','Ce mécanisme générique ne traite pas à lui seul les contraintes de présentation du magasin.')],
    ['RELEX apporte l’angle magasin et place disponible ; Microsoft illustre le calcul de seuils locaux. Leurs périmètres se complètent sans décrire une même fonction exacte.', 'FLOW retient le rôle du magasin : choisir sa cible selon le service attendu et ses contraintes. Optimiser plusieurs magasins séparément ne constitue pas un arbitrage multi-échelon.'],
    ('auto','Illustration FLOW — petite réserve, livraisons fréquentes','Un petit magasin veut exposer la collection sans saturer sa réserve.','La cible tient compte des ventes attendues avant la livraison suivante et de la place disponible.','Le comportement ne redessine pas l’assortiment et ne produit pas encore la commande d’apport.'))

add('BHV027','Dimensionner le stock qui permet au centre de distribution de servir ses destinataires : Distribution Center Inventory Optimization choisit ses objectifs et seuils. Il ne traite ni rangement ni productivité du prélèvement.',
    'Stock cible des centres alimentant magasins ou canaux.', 'Relier besoins aval et risques d’approvisionnement amont.',
    [('dc','Les besoins projetés des magasins alimentent le stock de sécurité des centres.','La solution RELEX couvre aussi flux et capacité, au-delà de cette décision de cible.'),('targets','Des minima peuvent être calculés à la maille produit et entrepôt.','Une approche locale Microsoft n’établit pas une optimisation conjointe de tous les magasins.')],
    ['RELEX rend visible la dépendance aux commandes magasins projetées ; Microsoft montre une détermination de minima à la maille de couverture. Agréger la demande aval est nécessaire sans imposer de recalculer toutes les cibles du réseau.', 'FLOW distingue le centre par son rôle d’approvisionnement. La cible de stock est séparée des décisions de manutention et d’organisation des équipes.'],
    ('dc','Illustration FLOW — servir vingt magasins','Un centre dessert vingt magasins avec un délai fournisseur variable.','Son objectif de stock intègre les besoins projetés de ces magasins et les aléas amont.','La décision peut rester centrée sur ce dépôt ; elle n’est multi-échelon que si les cibles des autres niveaux sont arbitrées ensemble.'))

add('BHV028','Répartir les marges de stock entre plusieurs niveaux du réseau : Multi-Echelon Inventory Optimization détermine des cibles cohérentes entre elles. Il évite de traiter chaque lieu comme si les autres n’existaient pas.',
    'Objectifs conjoints des centres, entrepôts et magasins concernés.', 'Tenir compte des dépendances de service et de risque.',
    [('meio','SAP optimise ensemble la sécurité et les services internes du réseau.','L’objectif de coût sous service SAP n’impose pas les priorités FLOW.'),('science','Le modèle scientifique intègre dépendances et contraintes multi-échelons.','Le cas pharmaceutique et ses hypothèses ne sont pas transposés quantitativement au textile.')],
    ['SAP et Achkar et ses coauteurs relient les niveaux de stock par les délais et engagements de service. La recherche explicite un modèle mathématique ; SAP décrit un opérateur de planification.', 'FLOW retient le mécanisme de décision conjointe. Le résultat peut déplacer la sécurité vers l’amont ou l’aval, sans centralisation systématique ni gain garanti.'],
    ('meio','Exemple SAP — où porter la sécurité ?','Le cours compare une marge dans un entrepôt interne et une marge au point qui sert le client.','Le coût de détention et le service entre niveaux changent le partage préférable.','La bonne réponse dépend des liens du réseau ; additionner des optimisations locales ne résout pas ce choix.'))

add('D05.g','Donner aux magasins le stock nécessaire au lancement : Initial Stocking Decision détermine les premiers apports et leurs dates à partir de l’assortiment retenu. Elle reste distincte du réassort pendant la vente.',
    'Quantités et dates d’implantation par magasin.', 'Adapter le lancement aux besoins locaux et aux contraintes.',
    [('nextail','First Allocation vise la distribution initiale des nouveaux produits.','La fonction inclut des prévisions produit ; FLOW peut les recevoir sans absorber leur production.'),('sapalloc','Le scénario SAP commence par l’implantation d’une collection.','Retail Allocation couvre aussi les redistributions ultérieures, plus larges que cette décision.')],
    ['Nextail nomme First Allocation le lancement ; SAP Retail Allocation suit une collection du premier apport aux ajustements ultérieurs. Leur mot Allocation ne désigne pas l’affectation de ressources à des Orders dans FLOW.', 'FLOW préfère Initial Stocking Decision pour rendre clair le résultat et sa frontière. L’assortiment est déjà retenu ; cette décision choisit les quantités et dates de démarrage.'],
    ('sapalloc','Exemple SAP — première allocation de la collection','Après examen du plan d’assortiment, le responsable demande la première répartition en magasins.','L’allocateur utilise la situation des achats pour préparer l’implantation.','L’intention d’assortiment et les ressources attendues éclairent l’apport initial, sans se confondre avec lui.'))

add('D05.e','Maintenir la disponibilité pendant la commercialisation : Replenishment Decision détermine les apports successifs et les ajustements utiles. Les commandes et déplacements qui les concrétisent restent distincts.',
    'Quantités et dates de réassort, y compris révision d’apports prévus.', 'Confronter besoins, cibles, ressources attendues et contraintes.',
    [('saprepl','Le réassort rapproche la situation de stock et les besoins.','SAP génère aussi les documents suivants ; FLOW distingue le résultat de décision et les Orders.'),('quantity','Microsoft distingue besoin daté et retour vers une cible.','Les méthodes et contraintes de lot ne constituent pas des capacités autonomes.')],
    ['SAP expose la chaîne allant du stock au besoin puis au document d’approvisionnement ; Microsoft détaille les différentes méthodes de calcul. Les deux éclairent Replenishment, avec des découpages produits différents.', 'FLOW conserve les calculs dans la décision et distingue l’apport initial de lancement. Réviser un apport existant peut éviter d’en créer un second pour le même besoin.'],
    ('quantity','Exemple Microsoft — retrouver un niveau de stock','Dix pièces sont présentes, le minimum vaut quinze et le maximum vingt-deux, sans autre besoin ni apport.','Sans contrainte de multiple, Microsoft propose douze pièces.','Le résultat est un apport nécessaire ; sa mise en commande n’est pas la même responsabilité.'))

add('BHV083','Apporter ce qui manque pour les besoins datés : Requirement-based Replenishment calcule les quantités et dates complémentaires après les ressources utilisables. Un besoin peut être prévu ou agrégé, sans être une commande client unitaire.',
    'Besoins nets sur un horizon et apports nécessaires.', 'Éviter les doublons avec le présent et l’attendu admissibles.',
    [('coverage','Requirement et Period répondent à des besoins identifiés.','FLOW réunit ces modalités sans créer un comportement par cadence.'),('quantity','Les contraintes de lot modifient l’apport nécessaire.','Le manque arithmétique ne suffit pas à établir une quantité réalisable à temps.')],
    ['Microsoft documente dans deux pages complémentaires les modes par besoin ou période et les contraintes qui modifient leurs quantités. Ce sont deux documents d’un même éditeur, pas une preuve de consensus.', 'FLOW retient le principe du besoin net : la demande, les ressources admises et les dates restent expliquées. La recommandation ne vaut ni réservation ni promesse.'],
    ('coverage','Illustration FLOW — trente pièces encore à apporter','Cent vingt pièces sont nécessaires à J+7 ; soixante-dix sont utilisables et vingt arrivent à temps.','Le besoin complémentaire est trente, avant vérification des lots et délais.','Une réception déjà comptée dans les vingt attendues ne doit pas devenir un apport nouveau supplémentaire.'))

add('BHV084','Rétablir le stock vers la cible retenue : Target-based Replenishment détermine l’apport lorsque les seuils applicables le demandent. Il utilise les objectifs sans les redéfinir.',
    'Apports calculés à partir du stock projeté, des seuils et de la cible.', 'Prendre en compte l’attendu et les contraintes de quantité.',
    [('quantity','Le min/max compare position projetée et niveaux retenus.','Les multiples peuvent empêcher d’atteindre exactement le maximum.'),('policies','Oracle relie déclenchement et reconstitution de la cible.','La façon Oracle de calculer les paramètres n’est pas imposée dans ce comportement.')],
    ['Microsoft montre l’effet des conditionnements sur une cible ; Oracle distingue le seuil qui déclenche et la quantité visée. Une cible n’est donc ni un ordre ferme ni nécessairement le résultat exact après arrondi.', 'FLOW utilise les paramètres d’Inventory Target Decision. Il expose les écarts dus aux contraintes au lieu de réécrire silencieusement la cible.'],
    ('quantity','Exemple Microsoft — le multiple change l’apport','Avec dix présentes, un minimum de quinze, un maximum de vingt-deux et des lots de cinq, le complément exact serait douze.','Microsoft propose dix pièces dans cet exemple, pour ne pas dépasser le maximum.','Les règles d’arrondi doivent être explicites ; cet exemple produit n’impose pas ce choix à toutes les décisions FLOW.'))

add('BHV085','Réviser les apports déjà prévus lorsque le besoin change : Replenishment Adjustment recommande les modifications admissibles de quantité ou de date. Une recommandation ne modifie pas à elle seule un engagement.',
    'Augmentation, réduction, avance, report ou annulation d’apports.', 'Respecter fermeté, réalisations et possibilités réelles de changement.',
    [('actions','Les Action messages recommandent des ajustements.','Microsoft calcule des suggestions ; leur acceptation et application restent à distinguer.'),('plans','Les horizons et le gel encadrent les changements possibles.','Les réglages d’un plan ne résument pas tous les accords fournisseurs et engagements FLOW.')],
    ['Microsoft sépare les messages qui suggèrent une adaptation et le cadre du plan qui autorise ou gèle certains changements. Les quantités souhaitables ne sont pas toutes modifiables.', 'FLOW conserve cette vérification dans le résultat : ce qui peut changer, ce qui reste engagé et l’écart résiduel. D04 applique ensuite les changements autorisés.'],
    ('actions','Exemple Microsoft — trente demandées en plus, quarante suggérées','La demande augmente de trente pièces alors que les apports doivent être des multiples de vingt.','Microsoft recommande une hausse de quarante.','Le supplément est expliqué par la contrainte de lot ; il ne constitue pas encore une confirmation du fournisseur.'))

add('D05.c','Mieux utiliser le stock déjà présent dans le réseau : Stock Redistribution Decision détermine les transferts utiles entre sites. Elle peut répondre à un manque ou rendre des stocks dispersés plus utiles.',
    'Origines, destinations, quantités et dates de redistribution.', 'Comparer bénéfices, coûts, délais et besoins des donneurs.',
    [('rebalance','Oracle recommande des transferts d’excédents vers les besoins.','Le calcul Oracle à la date initiale n’épuise pas tous les horizons FLOW.'),('merkal','La consolidation des tailles améliore l’utilité locale du stock.','Le cas Merkal est une expérience rapportée, pas une règle générale de gain.')],
    ['Oracle part d’un déséquilibre entre excédents et manques ; Nextail illustre avec Merkal l’intérêt d’une meilleure réunion des tailles. Les transferts peuvent donc servir plusieurs bénéfices.', 'FLOW retient Stock Redistribution pour cette décision sur le stock existant. Les achats nouveaux, les Orders de transfert et les prestations physiques restent distincts.'],
    ('merkal','Exemple Nextail — regrouper les tailles chez Merkal','Le cas Merkal décrit des scénarios de fin de saison sur son réseau de magasins.','Une meilleure consolidation des tailles rend les assortiments plus disponibles localement.','Ce bénéfice éclaire la redistribution, sans présumer les quantités, coûts ou gains applicables à FLOW.'))

add('BHV024','Rééquilibrer le stock vers les lieux où il sera plus utile : Inventory Rebalancing recommande des transferts en préservant le donneur. Le déplacement physique est l’effet recherché, pas l’action réalisée par cette décision.',
    'Redistribution selon besoins présents ou prévus.', 'Confronter le besoin destinataire et la couverture du donneur.',
    [('rebalance','Le calcul rapproche surplus et déficits en gardant une sécurité donneur.','Oracle ne réalise pas une évaluation temporelle continue dans cette fonction.'),('nextail','Store Transfers recommande les mouvements selon les ventes projetées.','L’angle magasin Nextail est plus ciblé que tout réseau FLOW.')],
    ['Oracle exprime l’écart entre lieux ; Nextail s’appuie sur les ventes projetées en magasin. Les deux justifient de déplacer du stock existant plutôt que commander systématiquement du nouveau.', 'FLOW n’exige pas d’attendre la rupture. Le transfert doit rester utile à sa date d’arrivée et compatible avec les engagements du donneur.'],
    ('rebalance','Illustration FLOW — un transfert qui arrive à temps','Un magasin risque de manquer de vingt pièces alors qu’un autre est suffisamment couvert.','La décision recommande vingt pièces si délai et coût du transfert sont acceptables.','Un excédent apparent ne suffit pas : le donneur doit conserver ses besoins et engagements.'))

add('BHV025','Redonner une utilité à des quantités dispersées : Stock Consolidation décide où les réunir. Il peut s’agir de reconstituer des tailles ou de regrouper des reliquats, sans imposer une pénurie à destination.',
    'Regroupement intersites de stocks fragmentés.', 'Comparer utilité de la concentration et besoins locaux.',
    [('merkal','Merkal rapporte un bénéfice de consolidation des tailles.','Cette expérience ne signifie pas que chaque taille dispersée est excédentaire.'),('rebalance','Oracle peut diriger les excédents vers un lieu de collecte.','Un sweep location ne décrit pas à lui seul la reconstitution d’un assortiment.')],
    ['Nextail éclaire le regroupement des tailles ; Oracle documente un lieu recevant les excédents. Ce sont deux usages de concentration, avec des critères différents.', 'FLOW les réunit sans absorber la conception d’assortiment, la liquidation ni la destruction. La consolidation d’emplacements ou de palettes à l’intérieur d’un entrepôt reste un autre sujet.'],
    ('merkal','Illustration FLOW — des tailles dispersées','Trois magasins portent chacun quelques tailles d’un même modèle.','Une partie des pièces est regroupée dans un magasin où l’ensemble répond mieux aux besoins.','La gamme n’est pas redéfinie et les besoins des magasins donneurs restent protégés.'))

add('D05.f','Préparer et maintenir un scénario de stock cohérent : Inventory Planning construit des alternatives, en examine les effets et adapte le scénario retenu. Il mobilise les décisions spécialisées et les responsables de leur mise en action.',
    'Scénarios alternatifs et trajectoire de stock en cours.', 'Articuler hypothèses, résultats, choix et suites opérationnelles.',
    [('simulation','Oracle permet de varier politiques, demandes et apports avant application.','La page décrit une fonction de plan, pas l’ensemble des responsabilités FLOW.'),('plans','Microsoft distingue plans opérationnels et simulations.','Un plan produit regroupe aussi des calculs spécialisés que FLOW garde identifiés.')],
    ['Oracle détaille les variantes à simuler ; Microsoft décrit la coexistence de plans et leurs horizons. Tous deux rendent possible une préparation avant mise en action.', 'FLOW nomme Inventory Planning la construction et le maintien de cette cohérence. Planning mobilise des décisions ; il n’en devient pas la décomposition hiérarchique.'],
    ('simulation','Illustration FLOW — deux niveaux de service','Le métier compare un scénario prudent avec davantage de sécurité et un scénario moins immobilisant.','Les effets sur disponibilité, stock et besoins d’apport sont projetés avant le choix.','Retenir un scénario déclenche les responsables utiles ; cela ne signifie pas que toutes les opérations sont déjà réalisées.'))

add('BHV005','Préparer plusieurs réponses possibles avant de choisir : Scenario Construction explicite leurs hypothèses, objectifs et contraintes. Créer une alternative métier dépasse la simple copie d’un plan.',
    'Variantes de scénario de stock cohérentes.', 'Faire varier les hypothèses sans masquer ce qui reste commun.',
    [('simulation','Oracle propose de faire varier politiques, ressources ou demandes.','Les variantes de paramètres ne sont pas automatiquement des choix métier pertinents.'),('plans','Microsoft permet des plans pour plusieurs prévisions ou stratégies.','FLOW ne prescrit ni nombre de plans ni outil pour les porter.')],
    ['Oracle fournit des leviers de variation ; Microsoft donne le cadre de plans parallèles. Les deux permettent d’explorer des réponses sans remplacer immédiatement le plan de référence.', 'FLOW retient le travail de construction : nommer ce qui change et pourquoi, puis mobiliser les décisions nécessaires. Les résultats devront encore être simulés et analysés.'],
    ('simulation','Illustration FLOW — dix ou quinze jours de couverture','Les mêmes besoins et contraintes sont conservés dans deux alternatives.','L’une vise dix jours de couverture, l’autre quinze ; leurs conséquences restent à calculer.','Le scénario décrit une hypothèse compréhensible, pas un simple fichier dupliqué.'))

add('BHV006','Comprendre les conséquences d’un scénario avant de l’adopter : Simulation & Analysis projette les résultats et explique les compromis. Les recommandations produites éclairent le choix sans devenir des engagements.',
    'Effets sur service, stock, coûts et processus concernés.', 'Comparer les résultats et rendre les causes lisibles.',
    [('simulation','Oracle compare situation de référence et variantes simulées.','Un résultat simulé ne prouve pas que le fournisseur ou l’exécutant pourra l’appliquer.'),('actions','Microsoft propose des ajustements expliqués par besoins et contraintes.','Une recommandation de calcul n’est pas une décision métier adoptée.')],
    ['Oracle montre la comparaison de résultats avant libération ; Microsoft produit des suggestions sur les apports. Leur point commun est une information pour agir, avec un statut encore distinct de l’action.', 'FLOW réunit projection et interprétation dans un même comportement. Il faut expliquer les lieux qui gagnent ou perdent, pas seulement afficher un indicateur global.'],
    ('simulation','Illustration FLOW — plus de service, plus de stock','Un scénario améliore le service estimé mais augmente le stock immobilisé.','L’analyse localise les magasins bénéficiaires et ceux dont le risque d’excédent augmente.','Le choix dépend des objectifs ; aucun gain simulé n’est présenté comme une réalisation acquise.'))

add('BHV016','Garder le scénario de stock cohérent malgré les écarts : Scenario Execution Adaptation réexamine sa trajectoire avec les faits et les actions engagées. Les responsables opérationnels gardent leurs décisions et mises à jour.',
    'Adaptation du scénario en cours à la réalité observée.', 'Coordonner les révisions sans oublier les réalisations acquises.',
    [('plans','Un plan peut être recalculé avec les besoins et ressources actualisés.','Le recalcul ne remplace pas les autorisations de modifier un engagement.'),('actions','Les messages proposent avances, reports ou ajustements de quantité.','FLOW doit aussi conserver les suites déjà réalisées, au-delà des suggestions de l’outil.')],
    ['Microsoft relie plans actualisés et recommandations d’ajustement. Un nouveau calcul peut révéler ce qu’il faudrait changer, sans rendre tous les changements possibles.', 'FLOW retient l’adaptation de la trajectoire : mobiliser les décisions spécialisées, connaître leur prise en compte et préserver les faits acquis. Le pilotage des prestations reste dans Process Management.'],
    ('actions','Illustration FLOW — le fournisseur décale une livraison','Une livraison est reportée alors que certains transferts sont déjà expédiés.','Le scénario réexamine les apports et redistributions possibles sans annuler fictivement les quantités parties.','Les recommandations tiennent compte de l’exécution ; elles ne la réécrivent pas.'))

add('D05.i','Choisir le devenir logistique d’un produit retourné : Return Disposition Decision utilise son état constaté, les règles applicables et la valeur récupérable. Décider son orientation ne réalise ni inspection, ni remboursement, ni traitement physique.',
    'Remise en stock, réparation, renvoi ou autre filière autorisée.', 'Évaluer les options possibles et leurs conditions.',
    [('dispo','Microsoft sépare motif du retour et orientation du bien.','Les codes produit comprennent des suites commerciales que FLOW garde distinctes.'),('by','Blue Yonder confronte état, destination et potentiel de revente.','L’offre inclut aussi admissibilité du retour et remboursement, hors de cette décision.')],
    ['Microsoft présente les issues et leurs règles ; Blue Yonder insiste sur le meilleur devenir selon le contexte. Les politiques peuvent borner l’optimisation, sans opposition entre règles et calcul.', 'FLOW conserve la décision sur le bien retourné. L’accord commercial, le remboursement et les prestations nécessaires restent dans leurs périmètres propres.'],
    ('by','Exemple Blue Yonder — choisir le lieu du retour','Le même article peut revenir vers un entrepôt économique ou un magasin offrant de meilleures chances de revente.','Smart Disposition examine ces destinations selon les caractéristiques du retour.','FLOW retient le principe d’orientation ; les transferts du réseau et la réalisation restent coordonnés avec leurs responsables.'))

add('BHV048','Orienter un retour de façon cohérente lorsque les règles suffisent : Policy-based Disposition applique une politique au cas constaté. Le résultat reste conditionné par la qualité des informations reçues.',
    'Orientation selon état, catégorie et règles applicables.', 'Choisir une issue autorisée sans réinventer la règle à chaque cas.',
    [('dispo','Des codes et actions décrivent le devenir retenu.','Un code n’est pas un comportement et ne prouve pas l’inspection du produit.'),('by','Des règles et motifs contribuent au choix de la filière.','Blue Yonder couvre aussi la politique commerciale du retour, distincte dans FLOW.')],
    ['Microsoft décrit un vocabulaire d’issues ; Blue Yonder permet des règles qui orientent le retour. Les deux soutiennent une décision reproductible à partir d’un cas qualifié.', 'FLOW nomme le mécanisme de décision, pas l’administration des règles. Une politique peut délimiter les issues que Value Recovery Optimization comparera ensuite, sans séquence imposée.'],
    ('dispo','Illustration FLOW — réparer selon la politique','L’inspection indique un défaut réparable et la catégorie du produit autorise cette filière.','La règle oriente le produit vers la remise en état.','La décision utilise le constat ; elle ne réalise pas elle-même la réparation ni la remise en stock.'))

add('BHV049','Préserver la valeur d’un retour en comparant ses devenirs autorisés : Value Recovery Optimization confronte récupération possible, coûts, délais et risques. Une issue plus rentable ne rend pas une filière interdite acceptable.',
    'Comparaison de plusieurs orientations logistiques permises.', 'Expliquer le compromis de valeur au-delà d’une règle uniforme.',
    [('by','Le potentiel de revente et les coûts éclairent le routage.','La promesse commerciale d’optimisation ne donne pas les pondérations ni les résultats FLOW.'),('dispo','Les filières de réparation, revente ou renvoi forment des alternatives.','Microsoft décrit les issues sans démontrer un calcul qui les départage selon leur valeur.')],
    ['Blue Yonder éclaire le choix selon valeur et destination ; Microsoft documente des alternatives concrètes. La deuxième source définit des issues, elle ne prouve pas à elle seule leur optimisation.', 'FLOW conserve la comparaison de devenirs autorisés, avec plusieurs objectifs possibles. Le choix ne rembourse pas le client et ne réalise pas le traitement du produit.'],
    ('by','Illustration FLOW — réparer avant la fin de saison','Une pièce peut être réparée puis revendue, orientée vers la seconde main ou renvoyée au fournisseur selon les accords.','La décision compare valeur récupérable, coût et délai de chaque issue permise.','Un délai trop long peut rendre une réparation peu intéressante ; les contraintes obligatoires restent prioritaires.'))

add('TER003','Désigner ce qui peut être mobilisé pour un résultat : Ressource couvre un bien, un moyen ou un droit, sous des conditions explicites. Ce terme de travail est plus large que le stock de marchandises.',
    'Biens, moyens et droits mobilisables.', 'Préciser disponibilité, accès et usage admissible.',
    [('plans','La planification confronte besoins et moyens disponibles, y compris des capacités.','Master plan est un dispositif de planification ; il ne donne pas une définition générale de Ressource.'),('pal','Un droit de confirmation peut limiter l’accès à une quantité.','Un plafond n’est ni une marchandise supplémentaire ni une garantie d’obtenir le stock.')],
    ['Microsoft éclaire les moyens pris en compte pour répondre aux besoins ; SAP montre qu’un droit peut limiter leur accès. Les documents ne proposent pas le même objet ni une définition commune du mot ressource.', 'FLOW utilise Ressource comme terme englobant, puis nomme le bien, le moyen ou le droit concerné. La quantité et l’information qui le représente ne doivent pas être comptées comme deux ressources physiques.'],
    ('pal','Illustration FLOW — cent pièces, un accès limité','Cent pièces existent dans le réseau, mais un groupe ne peut en confirmer que vingt sur la période.','Le stock vaut cent ; le droit de ce groupe borne son accès à vingt.','La ressource physique et la règle d’accès ont des rôles différents.'))

add('TER005','Parler des biens présents dans un périmètre à une date : Stock désigne ici les marchandises. Leur existence, leur propriété et leur disponibilité restent trois questions distinctes.',
    'Biens matériels du périmètre considéré.', 'Dater le périmètre et distinguer présence et disponibilité.',
    [('sapinv','Inventory Management suit quantités, propriété et états du stock.','Le périmètre SAP comprend aussi la valorisation, que le terme Stock ne porte pas à lui seul.'),('onhand','La quantité physique diffère de la quantité disponible.','La liste est une représentation enregistrée ; elle ne prouve pas seule la présence réelle.')],
    ['SAP relie le stock à des qualifications et à sa valeur ; Microsoft distingue plusieurs quantités pour une même marchandise. Aucun de ces usages ne justifie de traiter tout stock comme librement utilisable.', 'FLOW retient le sens matériel. Une réservation, un blocage ou une propriété fournisseur expliquent son usage possible sans créer un second ensemble de biens.'],
    ('onhand','Illustration FLOW — présentes mais pas toutes disponibles','Cent pièces sont présentes dans un entrepôt ; vingt sont réservées et dix bloquées.','Le stock physique reste cent, alors que la quantité utilisable dépend des règles retenues.','Stock ne signifie ni propriété acquise ni disponibilité immédiate pour toute demande.'))

add('TER006','Situer une quantité de stock sans perdre son contexte : Position de stock précise le produit, le lieu, la date et les dimensions métier utiles. Deux vues de la même quantité ne constituent pas deux stocks.',
    'Quantité datée à une maille explicite.', 'Conserver les dimensions nécessaires à son interprétation.',
    [('onhand','Les dimensions choisies modifient le détail et l’agrégation affichés.','Une ligne d’écran n’est pas une définition universelle de la position métier.'),('supply','Oracle restitue les quantités et leurs évolutions dans le temps.','Un solde projeté intégrant des apports futurs doit rester distingué de la position présente.')],
    ['Microsoft montre pourquoi un total change lorsqu’on détaille les lieux ou autres dimensions ; Oracle ajoute la lecture chronologique. Les deux rendent une quantité interprétable par son contexte.', 'FLOW nomme Position de stock cette quantité qualifiée. Le détenteur, le propriétaire ou l’état sont précisés lorsqu’ils changent le sens ; la copie du même fait dans un autre système ne crée pas de stock.'],
    ('onhand','Illustration FLOW — quarante pièces, deux lieux','Quinze pièces d’un article sont au magasin A et vingt-cinq au magasin B à la même date.','Les deux positions détaillées expliquent un total réseau de quarante.','Additionner le total réseau aux détails produirait un double compte.'))

add('TER007','Reconnaître ce qui change la situation de stock : Mouvement de stock désigne un fait, comme une réception ou un changement d’état. Une intention et le document qui l’annonce ne suffisent pas à établir ce fait.',
    'Faits qui modifient une position de stock.', 'Distinguer fait reconnu, enregistrement et correction.',
    [('journals','Les journaux enregistrent réceptions, transferts et ajustements.','Le journal représente le mouvement ; il n’est pas le déplacement physique lui-même.'),('epcis','Un événement porte lieu, date et contexte d’un fait sur les biens.','Tout événement de visibilité n’est pas un mouvement de stock ; un simple constat peut ne rien changer.')],
    ['Microsoft présente les enregistrements qui modifient les quantités ; GS1 organise la description et la correction des faits de visibilité. Les périmètres se recouvrent sans rendre journal, événement et mouvement synonymes.', 'FLOW part du changement reconnu. Une réservation peut changer une qualification du stock ; elle ne prouve aucune sortie physique.'],
    ('journals','Illustration FLOW — transfert annoncé puis réalisé','Un transfert de vingt pièces est demandé, puis son départ est constaté.','L’annonce exprime un projet ; le départ reconnu change les positions concernées.','Le même document peut porter plusieurs étapes : il faut identifier le fait effectivement acquis.'))

add('TER008','Identifier ce qui devrait devenir mobilisable : Ressource attendue comporte une date et des conditions de mise à disposition. Elle reste distincte d’une ressource déjà présente et d’un simple potentiel non daté.',
    'Apports attendus, datés et qualifiés.', 'Rendre explicites origine, échéance et conditions.',
    [('supply','Les commandes d’achat et transferts entrants alimentent les ressources futures.','Le bilan Oracle applique ses propres règles d’inclusion ; toute ligne attendue n’est pas également ferme.'),('reserve','Microsoft permet de réserver certaines quantités commandées mais non reçues.','La réservation de l’attendu n’en fait pas du stock physique déjà disponible.')],
    ['Oracle rend visibles les apports futurs ; Microsoft montre que certains peuvent soutenir un engagement avant réception. Visibilité, admissibilité et présence sont donc des propriétés différentes.', 'FLOW exige une date et des conditions pour parler de Ressource attendue. La source de l’attente et son degré de fermeté doivent permettre d’apprécier ce qu’elle peut réellement soutenir.'],
    ('supply','Illustration FLOW — trente pièces prévues demain','Trente pièces d’une commande fournisseur doivent être reçues demain.','Elles peuvent entrer dans une projection à demain si les règles l’autorisent, mais pas dans le stock présent aujourd’hui.','Une prévision d’achat encore sans date ne porte pas le même niveau d’attente.'))

add('TER016','Préserver une quantité pour une demande identifiée : Réservation de ressource enregistre cet engagement et ses effets sur les demandes concurrentes. Une simple affectation de ressource ne produit pas ce blocage.',
    'Engagement quantitatif en faveur d’une demande.', 'Préciser concurrence, durée, révision et consommation.',
    [('soft','La réservation diminue la quantité disponible pour d’autres canaux.','Soft décrit un mécanisme produit ; il ne signifie pas sans effet sur la concurrence.'),('orres','Oracle lie une demande à une quantité présente ou attendue.','Sa garantie est soumise au périmètre et aux règles du produit ; FLOW ne promet pas une réalisation physique irrévocable.')],
    ['Microsoft insiste sur l’effet partagé entre canaux ; Oracle sur le lien demande–ressource et sa maille. Leur point commun utile est un engagement qui change ce que les concurrents peuvent obtenir.', 'FLOW conserve cette frontière avec Supply Assignment : proposer une affectation n’est pas encore réserver. La portée de la réservation, ses révisions et sa consommation doivent être expliquées.'],
    ('soft','Exemple Microsoft — dix pièces retenues sur cent','Un canal réserve dix pièces alors que cent sont présentes.','L’autre canal voit quatre-vingt-dix pièces disponibles selon le mécanisme décrit.','Les dix pièces n’ont pas quitté le stock physique ; c’est la possibilité de les engager ailleurs qui change.'))

add('TER018','Comprendre l’Allocation de groupe des sources : elle peut attribuer une enveloppe d’usage à une population. Dans le texte courant FLOW, préciser « enveloppe de protection » ou « droit d’usage par groupe » évite de la confondre avec Supply Assignment.',
    'Terme de rapprochement historique pour les droits par groupe.', 'Qualifier le sens d’Allocation à chaque usage.',
    [('alloc','Inventory allocation protège une part pour des canaux ou groupes.','Le terme Microsoft ne désigne pas l’affectation de ressources à une commande FLOW.'),('pal','Product Allocation borne des confirmations par groupe et période.','Le plafond SAP ne garantit pas qu’une part de stock restera pour le groupe.')],
    ['Microsoft et SAP emploient Allocation avec des effets différents : enveloppe protégée chez Microsoft, limite de confirmation dans la page SAP. Le nom seul ne permet pas de déduire la protection obtenue.', 'FLOW conserve ce terme comme rapprochement historique et explicite le droit effectivement accordé. Il ne devient ni le nom générique de Supply Assignment ni un synonyme automatique de réservation.'],
    ('pal','Exemple SAP — un plafond ne garde pas les pièces','Dans l’exemple PAL, les groupes Nord et Sud ont des plafonds et d’autres clients peuvent aussi consommer le stock commun.','Un groupe peut ne pas obtenir sa limite si le stock a été consommé auparavant.','Décrire le droit réel évite de présenter un plafond comme une enveloppe garantie.'))

add('TER019','Préserver un usage face à certaines demandes concurrentes : Protection de ressource désigne une restriction d’accès explicite. Elle n’implique ni sortie physique ni garantie absolue de réalisation.',
    'Restrictions qui préservent une quantité pour un usage.', 'Nommer bénéficiaires, concurrents et conditions de levée.',
    [('alloc','Les enveloppes protègent une part contre d’autres groupes.','La protection porte sur un usage collectif, pas nécessairement une demande individuelle.'),('pal','Un plafond peut limiter la consommation d’un groupe.','Limiter un groupe ne suffit pas à garantir du stock à un autre ; l’effet protecteur doit être démontré.')],
    ['Microsoft décrit une part préservée ; SAP montre les limites d’un simple plafond dans un stock commun. Les deux mécanismes encadrent la concurrence, mais ne donnent pas le même droit au bénéficiaire.', 'FLOW utilise Protection pour l’effet recherché et précise le mécanisme retenu. Un blocage qualité peut également rendre indisponible, mais il n’est pas pour autant une protection en faveur d’un autre usage.'],
    ('alloc','Illustration FLOW — une part pour un lancement','Deux cents pièces sont préservées pour les magasins du lancement jusqu’à une date convenue.','Les autres usages ne peuvent pas consommer cette part tant que la règle s’applique.','Les droits du groupe, leur horizon et la libération du reliquat doivent être connus.'))

add('TER020','Limiter ce qui peut être confirmé : Plafond de confirmation fixe un maximum pour des critères et une période. Il ne promet pas que cette quantité sera effectivement disponible.',
    'Maximum confirmable par groupe, produit et période.', 'Cumuler les confirmations et contrôler la limite.',
    [('pal','SAP PAL limite des confirmations à partir de critères et de périodes.','La limite reste distincte d’une quantité de stock réservée au groupe.'),('alloc','Microsoft suit aussi une consommation maximale d’enveloppe.','Son mécanisme ajoute une part protégée ; cette propriété ne découle pas du seul plafond FLOW.')],
    ['SAP met l’accent sur la limite d’accès au stock commun ; Microsoft associe limite et protection d’une part. Les deux suivent une consommation, mais leurs conséquences pour les autres demandes diffèrent.', 'FLOW retient Plafond de confirmation pour exprimer uniquement le maximum. La disponibilité et la protection éventuelle restent des conditions séparées.'],
    ('pal','Illustration FLOW — autorisé jusqu’à cent, disponible à soixante','Un groupe peut confirmer au plus cent pièces sur la semaine, mais soixante seulement restent utilisables.','Le plafond n’autorise pas à confirmer cent si les autres conditions limitent la réponse à soixante.','Un droit maximal ne crée aucune ressource.'))

add('TER021','Rassembler des ressources selon des règles compréhensibles : Pool de ressources décrit ce regroupement et, s’il existe, son droit d’usage. Il ne signifie pas à lui seul stock logique, stock virtuel ou stock exclusivement protégé.',
    'Regroupement explicite de ressources et de droits associés.', 'Préciser appartenance, accès et consommation.',
    [('alloc','Microsoft part d’un pool commun pour distribuer des enveloppes.','Virtual pool décrit ici un regroupement produit ; il ne définit pas le Stock virtuel FLOW.'),('orres','La réservation Oracle peut viser une maille globale ou un sous-ensemble détaillé.','Un niveau de réservation n’est pas automatiquement un pool disposant de droits propres.')],
    ['Microsoft donne au pool un rôle de base commune à partager ; Oracle montre plusieurs niveaux de ciblage des ressources. Regrouper et réserver sont deux opérations différentes.', 'FLOW nomme les règles du pool : ressources incluses, éventuels recouvrements, bénéficiaires et consommation. Le nom ne permet pas d’inférer une exclusivité ni une disponibilité supplémentaire.'],
    ('alloc','Illustration FLOW — regrouper plusieurs dépôts','Les pièces admissibles de deux dépôts constituent un pool pour certaines demandes.','Le regroupement fournit une vue commune ; les restrictions de chaque pièce et les délais restent applicables.','Les biens déjà comptés dans les dépôts ne s’ajoutent pas une seconde fois dans le pool.'))

add('TER022','Expliquer par quoi une demande pourrait être satisfaite : Couverture d’une demande relie quantités, dates et conditions. Une couverture envisagée reste distincte d’une affectation retenue, d’une réservation ou d’une promesse.',
    'Lien qualifié entre une demande et ses réponses possibles.', 'Préciser quantité, date et statut de la couverture.',
    [('ps','Le pegging relie une ressource entrante à une demande.','Dans PeopleSoft, le lien vers l’attendu et la réservation après réception ont des effets distincts.'),('supply','Le bilan chronologique confronte ressources et demandes.','Un solde global positif ne prouve pas la couverture individuelle ni le respect de la date demandée.')],
    ['PeopleSoft documente des liens ciblés ; Oracle Cloud présente un bilan des besoins et apports. Les deux éclairent la satisfaction possible, à des mailles différentes.', 'FLOW conserve le statut de la relation. Le mot couverture ne transforme pas une possibilité en engagement ; il ne désigne pas non plus la durée globale de Couverture de stock.'],
    ('supply','Illustration FLOW — cent pièces couvertes en deux temps','Une demande de cent pièces pourrait mobiliser soixante présentes et quarante attendues.','Elle est couverte à temps seulement si les quarante sont admissibles et arrivent avant l’échéance utile.','Ce rapprochement ne réserve rien et ne vaut pas encore promesse au demandeur.'))

add('TER040','Nommer les biens qui existent réellement : Stock physique désigne leur présence dans le périmètre considéré. La quantité enregistrée doit pouvoir être rapprochée de cette réalité.',
    'Existence matérielle des biens à une date.', 'Distinguer présence réelle, mesure et enregistrement.',
    [('onhand','Physical inventory est distingué de la quantité disponible.','La valeur affichée provient des enregistrements ; elle peut différer du comptage réel.'),('physical','L’inventaire physique compare le constat aux quantités enregistrées.','Physical Inventory peut nommer une opération de comptage, alors que FLOW nomme ici les biens présents.')],
    ['Microsoft emploie Physical inventory pour une quantité dans la vue de stock ; Oracle l’emploie aussi pour le contrôle complet de cette quantité. Le contexte distingue objet observé et méthode de contrôle.', 'FLOW retient le sens matériel pour Stock physique. Une pièce réservée, bloquée ou appartenant au fournisseur reste physique tant qu’elle est présente.'],
    ('physical','Illustration FLOW — quatre-vingt-dix-huit réellement comptées','Le système indique cent pièces ; un comptage fiable en trouve quatre-vingt-dix-huit au même périmètre et au même repère temporel.','L’écart de deux doit être expliqué avant correction.','Une valeur enregistrée n’est pas à elle seule la preuve du stock physique.'))

add('TER041','Décrire les états métier des mêmes biens : Stock logique qualifie le stock physique selon ses usages et restrictions. Ces états ne sont pas un second stock à additionner au premier.',
    'États métier du stock physique considéré.', 'Préciser les combinaisons et exclusions entre états.',
    [('statuses','Les statuts Microsoft distinguent notamment stock utilisable et bloqué.','Inventory status est une dimension produit ; le terme local Stock logique peut couvrir d’autres qualifications.'),('sapinv','SAP distingue des états et des stocks de propriété particulière.','Les catégories SAP ne forment pas une partition universelle à reprendre telle quelle.')],
    ['Microsoft montre l’effet d’un statut sur l’usage ; SAP ajoute d’autres qualifications, dont la propriété. Les classifications diffèrent et certaines dimensions peuvent se croiser.', 'FLOW garde Stock logique comme expression de travail pour ces états. Toute addition suppose de savoir si les catégories s’excluent ou se recouvrent ; réservé et consigné peuvent, par exemple, décrire des dimensions différentes.'],
    ('statuses','Illustration FLOW — cent pièces décrites par leurs états','Dans un exemple construit avec des catégories exclusives, cent pièces se répartissent en soixante libres, vingt réservées, dix allouées, cinq bloquées et cinq défectueuses.','La description totale reste cent pièces physiques.','Cette partition illustre le principe ; elle ne tranche pas les règles de combinaison des états dans FLOW.'))

add('TER042','Exprimer une disponibilité calculée : Stock virtuel dépend des quantités, dates et règles retenues. Ce résultat ne crée pas de marchandises et doit rester distingué du Stock physique.',
    'Quantité disponible selon un calcul explicite.', 'Nommer horizon, engagements et apports inclus.',
    [('onhand','Microsoft distingue disponible physique et disponibilité incluant des quantités commandées.','Available est le vocabulaire produit ; Stock virtuel est ici une expression de travail FLOW.'),('supply','Oracle combine apports et besoins selon des règles de calcul.','Un bilan futur et un disponible immédiat ne répondent pas à la même question.')],
    ['Microsoft donne plusieurs lectures de la disponibilité ; Oracle construit un bilan chronologique. Tous deux montrent que le résultat dépend de ce qui entre dans le calcul.', 'FLOW conserve Stock virtuel pour cette quantité calculée, sans lui attribuer une formule unique. Un engagement déjà soustrait d’une quantité de départ ne doit pas être déduit une deuxième fois.'],
    ('supply','Illustration FLOW — soixante-quinze disponibles à demain','Le calcul retient soixante pièces libres, trente reçues demain et quinze promises qui ne sont pas encore déduites des soixante.','Selon ces hypothèses, le disponible calculé à demain est soixante-quinze.','Le chiffre change si l’apport devient incertain ou si les quinze étaient déjà déduites ; ce n’est pas le stock physique présent.'))

add('TER043','Parler d’une disponibilité envisagée plus tard : Stock futur reste une expression de travail qui demande une date, un lieu et un degré de fermeté. Le potentiel non daté et la Ressource attendue qualifiée ne sont pas équivalents.',
    'Ressources envisagées ou attendues pour un usage futur.', 'Distinguer potentiel, prévu, engagé et déjà en transit.',
    [('supply','Oracle distingue les origines des apports futurs, dont achats et transferts.','La présence d’un type d’apport dans le bilan ne rend pas toutes ses lignes également certaines.'),('plans','Les plans peuvent produire des apports encore proposés.','Un résultat de plan n’est pas une commande confirmée ni un bien déjà reçu.')],
    ['Oracle montre des ressources entrantes déjà décrites ; Microsoft inclut des apports issus de la planification. Les degrés de fermeté diffèrent, même lorsque les deux concernent une disponibilité future.', 'FLOW garde cette expression exploratoire et exige la qualification du cas. Une pièce en transit existe physiquement quelque part mais reste future pour son site destinataire ; un potentiel fournisseur non daté est encore autre chose.'],
    ('supply','Illustration FLOW — présente sur la route, future au magasin','Vingt pièces ont quitté le dépôt et sont attendues demain au magasin.','Elles sont physiques dans le réseau et futures pour l’usage au magasin.','Le périmètre et la date empêchent de confondre absence locale et inexistence de la marchandise.'))

add('TER055','Comprendre les noms anglais du mouvement de stock : Stock movement et Inventory movement renvoient aux variations reconnues ; SAP utilise notamment Goods movement. Le mouvement reste distinct de son écriture justificative et ne suppose pas toujours un déplacement.',
    'Variations de quantité, lieu, état ou propriété.', 'Lire le sens du terme dans son contexte produit.',
    [('journals','Microsoft enregistre les variations dans différents journaux.','Le nom du journal indique le mode d’enregistrement, pas une identité entre écriture et fait.'),('sapinv','SAP utilise Goods movement dans sa gestion des stocks.','Les effets de valorisation présents dans SAP ne sont pas contenus dans tout mouvement FLOW.')],
    ['Microsoft met en avant Inventory journals ; SAP parle de Goods movements et de leurs effets de gestion. Ce sont des vocabulaires voisins dont les découpages dépendent des produits.', 'FLOW conserve Mouvement de stock pour le fait reconnu, y compris un changement d’état sans déplacement. Les écritures, messages et justificatifs décrivent ce fait sans devenir des mouvements supplémentaires.'],
    ('journals','Illustration FLOW — un transfert, deux écritures','Vingt pièces passent d’un lieu à un autre ; leur enregistrement comporte une sortie et une entrée.','Les deux écritures expliquent le transfert sans créer deux déplacements indépendants.','Le nombre de lignes du système ne détermine pas le nombre de faits métier.'))

add('TER056','Expliquer les variations du stock à l’aide d’un registre : Inventory Ledger est un nom rencontré pour cet historique. Dans FLOW, ce rapprochement reste exploratoire et n’adopte pas le candidat de capacité Inventory Ledger Management.',
    'Registre des écritures qui expliquent les variations.', 'Relier soldes, faits et corrections sans imposer une technologie.',
    [('ledger','Amazon rapproche les soldes et les mouvements dans un Inventory Ledger Report.','Il s’agit d’un rapport du réseau FBA, pas d’une définition universelle de capacité.'),('journals','Microsoft conserve les variations dans des Inventory journals.','Ses journaux peuvent entraîner des effets financiers ; ce périmètre ne découle pas du mot Ledger FLOW.')],
    ['Amazon emploie Ledger pour une lecture des soldes et événements ; Microsoft utilise Journal pour des enregistrements de gestion. Le service d’explication se rapproche, avec des usages et des responsabilités différents.', 'FLOW sépare le registre du mouvement qu’il décrit. Le sens comptable de grand livre ne suffit pas à imposer une valorisation financière, une architecture technique ou un nouveau nom de capacité.'],
    ('ledger','Illustration FLOW — expliquer le solde de quatre-vingt-dix','Une période commence à cent pièces, reçoit vingt pièces et en expédie trente.','Le registre explique le solde final de quatre-vingt-dix par ces variations reconnues.','L’exemple porte sur les quantités ; il ne décrit ni coût de stock ni écriture de grand livre comptable.'))

add('TER074','Apporter à nouveau du stock pendant son exploitation : Replenishment relie besoins et objectifs aux apports nécessaires. FLOW distingue la décision, sa mise en commande et la réalisation, sans imposer une intervention humaine entre elles.',
    'Réapprovisionnement selon besoins et objectifs applicables.', 'Déterminer l’apport puis mobiliser les suites autorisées.',
    [('saprepl','SAP calcule des besoins et prépare les suites d’approvisionnement.','Le parcours SAP associe calcul et documents ; FLOW conserve leurs responsabilités distinctes.'),('nextail','Nextail distingue Replenishment de First Allocation.','Son périmètre magasin ne définit pas tous les lieux et sources d’approvisionnement FLOW.')],
    ['SAP décrit l’enchaînement jusqu’aux documents d’approvisionnement ; Nextail distingue l’implantation initiale du réassort courant. Les deux utilisent Replenishment pour alimenter le stock selon les besoins.', 'FLOW conserve ce nom et distingue l’apport initial de lancement. Une décision peut être appliquée automatiquement si les règles l’autorisent ; elle ne devient pas pour autant une réception déjà réalisée.'],
    ('saprepl','Illustration FLOW — réassort du magasin','Les besoins et le stock projeté d’un magasin justifient vingt pièces supplémentaires.','La décision établit l’apport ; les responsables opérationnels déclenchent l’Order autorisé et sa réalisation.','Le réassort peut provenir d’un dépôt ou d’un fournisseur selon le cas ; le mot seul ne prescrit pas l’Order.'))

add('TER077','Comprendre combien de temps le stock peut répondre à une demande de référence : Couverture de stock est une mesure fondée sur des hypothèses explicites. Elle reste distincte d’un objectif de couverture et du lien à une demande particulière.',
    'Durée ou mesure de satisfaction de la demande par le stock.', 'Préciser demande, horizon, calendrier et ressources incluses.',
    [('days','SAP distingue durée couverte par le stock projeté et jours de couverture visés.','Le résultat dépend du calendrier et de la demande inclus ; FLOW ne généralise pas la formule SAP.'),('policies','Oracle utilise des jours de couverture pour calculer des niveaux de politique.','Un paramètre cible de jours n’est pas la couverture effectivement mesurée.')],
    ['SAP expose à la fois la mesure et ses objectifs ; Oracle utilise une durée pour dimensionner des seuils ou niveaux. Une valeur en jours peut donc décrire une situation ou prescrire une cible.', 'FLOW précise ce rôle et les hypothèses de calcul. La Couverture d’une demande désigne un autre lien, avec des ressources et un statut ; elle ne se déduit pas d’un nombre moyen de jours.'],
    ('days','Illustration FLOW — dix jours sous hypothèses constantes','Cent pièces sont disponibles et la demande de référence est constante à dix pièces par jour, sans apport ni autre restriction.','Cette situation représente dix jours de couverture selon ces hypothèses.','Des besoins irréguliers, des jours non ouvrés ou des réceptions futures exigent un calcul adapté.'))

add('VER003','Établir une réponse à partir des faits et règles utiles : Déterminer exprime le résultat attendu. Dans la convention FLOW, un calcul peut y contribuer sans être la seule façon de parvenir au résultat.',
    'Établissement d’un résultat métier.', 'Choisir les moyens nécessaires au résultat demandé.',
    [('targets','Un niveau de sécurité proposé peut être établi par un calcul.','L’application du résultat est distincte et la documentation ne définit pas le verbe français Déterminer.'),('by','Une orientation de retour dépend de règles et de la valeur récupérable.','Le produit décrit un service de décision, pas une convention normative sur les verbes.')],
    ['Microsoft éclaire un résultat quantitatif ; Blue Yonder un choix de devenir parmi plusieurs possibilités. Les moyens diffèrent, mais les deux conduisent à établir une réponse utile au métier.', 'FLOW emploie Déterminer pour cette finalité. Le nom ne crée pas une séquence humaine obligatoire et ne signifie pas que le résultat est déjà appliqué.'],
    ('by','Illustration FLOW — déterminer une filière de retour','L’état du produit et les règles permettent la réparation ou le renvoi au fournisseur.','La décision établit l’orientation retenue et ses conditions.','Des calculs de coût peuvent éclairer ce résultat ; le service rendu reste de déterminer le devenir.'))

add('VER004','Produire une valeur par des opérations quantitatives : Calculer annonce un résultat chiffré. FLOW conserve ce verbe lorsqu’il rend le service plus précis, sans imposer un algorithme.',
    'Établissement d’une valeur quantitative.', 'Rendre explicites données, règles et unité du résultat.',
    [('quantity','Microsoft calcule une quantité d’apport avec des règles de lot.','L’écart brut et la quantité arrondie peuvent différer ; les contraintes font partie du calcul.'),('policies','Oracle calcule des paramètres à partir de demande, délai et sécurité.','Ces formules sont des méthodes produit, pas la définition générale du verbe français.')],
    ['Microsoft illustre une quantité à commander ; Oracle des paramètres de réapprovisionnement. Les calculs portent sur des objets différents et utilisent des hypothèses différentes.', 'FLOW retient le sens quantitatif. Calculer peut faire partie de Déterminer ; cela n’exige ni une capacité autonome par formule ni une validation humaine systématique.'],
    ('quantity','Illustration FLOW — douze nécessaires, des lots à respecter','Le retour vers la cible demande douze pièces mais l’approvisionnement se fait par lots de cinq.','Le calcul doit appliquer une règle explicite pour obtenir une quantité réalisable.','Arrondir vers dix ou quinze ne va pas de soi : la politique choisie donne son sens au nombre.'))

add('VER009','Préserver une quantité pour un usage face à des concurrents identifiés : Protéger décrit cet effet. Il faut préciser le mécanisme et les règles de levée, car toutes les limites d’accès ne protègent pas de la même manière.',
    'Préservation d’un usage par restriction d’accès.', 'Expliciter bénéficiaire, concurrence et horizon.',
    [('alloc','Microsoft réserve des enveloppes d’usage à certains groupes.','Une protection collective ne devient pas une réservation pour une demande individuelle.'),('pal','SAP limite les confirmations de groupes dans un stock commun.','Ce plafond peut réduire une consommation sans garantir la quantité d’un autre groupe.')],
    ['Microsoft éclaire la part préservée ; SAP oblige à distinguer cette protection d’un simple maximum de confirmation. Employer le même verbe sans préciser l’effet masquerait cette différence.', 'FLOW utilise Protéger comme convention locale d’effet métier. Le bien reste présent ; ce sont certaines possibilités d’usage concurrent qui changent.'],
    ('alloc','Illustration FLOW — préserver le lancement','Une part est protégée pour un lancement et ne peut pas servir aux autres demandes avant une échéance.','Les concurrents sont limités selon la règle en vigueur.','Protéger exige un bénéficiaire et des conditions ; ce n’est pas déclarer une quantité inviolable pour toujours.'))

add('VER010','Attribuer une enveloppe à une population ou un usage : Allouer à un groupe précise le sens collectif de l’action. FLOW qualifie toujours ce verbe pour éviter la confusion avec l’affectation de ressources à une demande.',
    'Attribution de droits quantitatifs à un groupe.', 'Décrire enveloppe, horizon et consommation autorisée.',
    [('alloc','Inventory allocation donne une part à un canal ou groupe.','L’enveloppe collective ne désigne pas une correspondance ressource–commande.'),('pal','Product Allocation configure des limites selon des critères de groupe.','Ce mécanisme peut limiter sans préserver une part physique, contrairement à une lecture automatique du mot allouer.')],
    ['Microsoft et SAP illustrent deux sens d’Allocation par groupe, dont les protections diffèrent. Le complément du verbe ne dispense donc pas d’expliquer le droit obtenu.', 'Dans la convention FLOW, Allouer à un groupe signifie attribuer l’enveloppe définie. Le texte courant peut préférer « attribuer une enveloppe de protection » ; aucun synonyme général avec Supply Assignment n’est établi.'],
    ('alloc','Illustration FLOW — attribuer cent pièces au canal','Un canal reçoit un droit d’usage de cent pièces sur une période définie.','Sa consommation est suivie à l’intérieur de cette enveloppe.','Il reste à préciser si les pièces sont protégées et dans quelles conditions le reliquat peut revenir à d’autres usages.'))

add('VER011','Engager une quantité pour une demande identifiée : Réserver change les possibilités des demandes concurrentes. La portée et la durée de cet engagement doivent être connues.',
    'Engagement quantitatif en faveur d’une demande.', 'Préciser ressource, effets concurrents et fin de l’engagement.',
    [('orres','Oracle lie et protège une quantité pour une demande.','La maille peut rester globale ; réserver ne signifie pas forcément choisir immédiatement un lot.'),('ct','commercetools réserve au panier ou à la commande.','L’échéance d’une réservation de panier fait partie de son effet, pas d’une définition universelle de Réserver.')],
    ['Oracle met l’accent sur le lien à la ressource ; commercetools sur le moment et la durée dans le parcours commercial. Les deux montrent un engagement qui doit avoir des conditions.', 'FLOW emploie Réserver pour cet effet quantitatif. Une proposition d’affectation ou une vérification de disponibilité ne suffit pas à dire que la réservation existe.'],
    ('ct','Illustration FLOW — deux pièces pendant le panier','Deux pièces sont réservées pour un panier selon une règle de maintien de quinze minutes.','Elles ne peuvent pas être engagées ailleurs pendant ce maintien ; la règle traite ensuite expiration ou conversion.','La durée est illustrative : le verbe Réserver n’impose ni panier ni quinze minutes.'))

add('VER019','Rendre de nouveau possible un usage en levant une restriction : Libérer doit nommer ce qui est libéré. Dans les sources, Release peut aussi autoriser une étape de traitement, ce qui est un autre sens.',
    'Levée totale ou partielle d’une restriction ou d’un engagement.', 'Décrire l’effet obtenu sur les usages autorisés.',
    [('ct','La fin d’une réservation de panier rend la quantité à nouveau disponible.','La libération n’est ni une expédition ni une consommation physique.'),('ps','PeopleSoft distingue désengagement et passage d’une demande à un état libérable.','Release vers le traitement ne signifie pas nécessairement supprimer une réservation.')],
    ['commercetools éclaire la levée d’une retenue ; PeopleSoft montre un vocabulaire Release lié aussi à l’avancement d’une demande. Traduire automatiquement les deux par la même action serait trompeur.', 'FLOW précise le complément : libérer une quantité réservée ou lever une protection. Le verbe ne prouve aucune restitution matérielle ni annulation de tous les engagements voisins.'],
    ('ct','Illustration FLOW — le panier expire','Une réservation de deux pièces arrive à échéance sans conversion en commande.','La règle lève l’engagement et rend ces pièces de nouveau disponibles pour d’autres demandes.','Le stock physique n’a pas augmenté : seule la restriction a disparu.'))

add('VER020','Imputer une utilisation à la quantité ou au droit concerné : Consommer décrit ce qui est utilisé dans son contexte. Consommer une enveloppe, solder une réservation et sortir physiquement une pièce ne sont pas des synonymes.',
    'Utilisation d’une quantité, d’un droit ou d’un engagement.', 'Nommer l’objet consommé et ses effets.',
    [('alloc','La consommation d’une enveloppe diminue le droit restant du groupe.','Elle n’est pas à elle seule la preuve d’une sortie physique.'),('consign','L’utilisation d’une matière consignée peut entraîner son acquisition.','Le sens lié à la production et au transfert de propriété dépend de l’accord applicable.')],
    ['Microsoft utilise la consommation pour une enveloppe de droits et pour l’utilisation de matière consignée. Ces deux documents d’un même éditeur montrent précisément pourquoi le complément change le sens.', 'FLOW garde le verbe comme convention locale, en indiquant ce qui diminue ou est soldé. Les effets sur propriété, disponible et stock physique sont ensuite qualifiés séparément.'],
    ('alloc','Illustration FLOW — trente prises sur une enveloppe de cent','Un groupe utilise trente unités du droit qui lui avait été attribué.','Son enveloppe restante vaut soixante-dix selon la règle de consommation.','Cela ne prouve pas que trente pièces ont déjà quitté un entrepôt.'))

# Prior references are retained verbatim here even when the shorter table replaces them.
# This review is editorial evidence, not an update of the authority files or adoptions.
prior_review=[]
registered={document_key(s['source_url']):key for key,s in S.items()}
for ident,oldrecord in original_by_id.items():
    previous=oldrecord.get('fields',oldrecord).get('market_comparisons',[])
    current={document_key(c['source_url']) for c in OUT[ident]['market_comparisons']}
    old_counts={u:sum(document_key(c['source_url'])==u for c in previous) for u in {document_key(c['source_url']) for c in previous}}
    notes=[]
    for old in previous:
        url=old['source_url']; urlkey=document_key(url)
        if urlkey in current:
            outcome='retained_and_rewritten'
            reason='Passage consulté et référence conservée ; rédaction centrée sur le service métier et limites explicites.'
            if old_counts[urlkey]>1:
                outcome='merged_same_document'
                reason='Plusieurs anciennes entrées du même document regroupées ; une page ne compte qu’une fois et toutes ses anciennes sources sont conservées.'
        elif 'help.sap.com/docs/' in url:
            outcome='replaced_unavailable_extraction'
            reason='Ouverture tentée, sans texte exploitable dans la page SAP Help. Aucune actualisation factice de consultation ; remplacée par les passages accessibles indiqués dans la nouvelle table.'
            if '/PRODUCT_ID/9832125c' in url:
                reason+=' Le rapprochement ancien concernait en outre la consolidation interne à l’entrepôt, distincte de la décision de regroupement intersites.'
        elif 'ibm.com/docs/' in url:
            outcome='replaced_unavailable_extraction'
            reason='Consultation tentée : erreur d’accès, ou HTTP 403 pour SIP Reservations. La preuve antérieure est conservée ici ; les nouveaux textes reposent sur des documents accessibles.'
        elif 'manh.com/' in url:
            outcome='replaced_after_reading'
            reason='La page actuelle lue présente surtout le parcours commercial de retour et échange ; elle ne donne pas le passage nécessaire sur le choix de filière selon la valeur récupérable.'
        elif 'oasis-open.org/' in url:
            outcome='replaced_after_reading'
            reason='UBL 2.4 documente des messages commerciaux ; sa présence ne démontre pas une décision d’implantation ni un choix de sortie de consignation. Des preuves métier au niveau du service remplacent ce rapprochement trop éloigné.'
        elif 'logility.com/' in url:
            outcome='replaced_after_reading'
            reason='Présentation textuelle du cas Groupe Dynamite consultée ; vidéo non visionnée. Le texte annonce distribution initiale et réassort sans donner le détail retenu. Les passages Nextail et SAP Learning sont plus précis pour la comparaison.'
        elif urlkey in registered:
            outcome='replaced_after_reading'
            reason={
                'D01.f':'La réservation est documentée mais ne définit pas la tenue de stock ; les journaux et la liste des quantités étayent directement Tracking.',
                'D01.c':'La réservation diminue le disponible mais la fiche porte sur sa lecture ; les vues des quantités et du bilan attendu couvrent plus directement Visibility.',
                'D05.a':'La table retient deux descriptions précises du calcul des paramètres ; les développements généraux ou les variantes de réseau sont portés par leurs fiches dédiées.',
                'D05.g':'La table privilégie les descriptions explicites First Allocation et Retail Allocation ; le cycle saisonnier RELEX est utile mais moins précis pour l’implantation seule.',
                'D05.e':'Le tableau de la capacité retient les apports et leurs quantités ; méthodes détaillées, sécurité et ajustements sont expliqués dans les comportements et termes concernés.',
                'BHV026':'Les passages RELEX saison/espace et Microsoft paramètres locaux décrivent plus directement la cible magasin que l’introduction générale à l’optimisation.',
                'BHV028':'Le cours SAP et le résumé scientifique expliquent directement le mécanisme entre échelons ; la présentation générale RELEX est conservée au niveau du domaine.',
                'BHV024':'Le cas Merkal éclaire surtout la consolidation des tailles ; la page Nextail Store Transfers décrit plus directement le rééquilibrage selon les ventes projetées.',
                'BHV006':'Le document Oracle de simulation étaye directement la comparaison de variantes ; les plans Microsoft restent documentés dans Inventory Planning.',
                'BHV084':'Les modalités de couverture Microsoft sont précisées dans le document sur les quantités ; Oracle apporte une seconde définition des paramètres min/max.',
                'D05.h':'La fiche explique trois familles de choix ; les cas de parcours détaillés restent sourcés dans leurs comportements propres.',
                'BHV034':'Les politiques de réservation et la réservation sur ressource attendue décrivent le mécanisme retenu ; le parcours de production n’est pas imposé à toute demande.',
                'D01.h':'Les déclencheurs de propriété structurent la comparaison de consignation ; le détail du retour est porté par Consignment Exit.',
                'BHV063':'La source sur l’ancienneté décrit le comportement voisin Aging-Based Ownership Transfer ; elle ne prouve pas un déclenchement par utilisation.',
            }.get(ident,'Document lu et non répété : la table retient les deux passages les plus directement utiles au nom et au mécanisme de cette fiche ; les preuves antérieures restent disponibles.')
        else:
            raise AssertionError(('prior_reference_without_review',ident,url))
        if outcome.startswith('replaced') or outcome=='merged_same_document':
            notes.append(f"{old['source_title']} : {reason}")
        prior_review.append(dict(target=ident,disposition=outcome,reason=reason,previous_comparison=deepcopy(old)))
    if notes:
        OUT[ident]['editorial_notes']=list(dict.fromkeys(notes))

OUT['TER018'].setdefault('editorial_notes',[]).append('Terme historique conservé ; aucun renommage ni accord nouveau. Le texte courant précise enveloppe de protection ou droit d’usage par groupe.')
OUT['TER041'].setdefault('editorial_notes',[]).append('La partition chiffrée est l’illustration FLOW issue de U76, reprise sans adopter une règle générale de combinaison des états.')
OUT['TER042'].setdefault('editorial_notes',[]).append('Le calcul illustratif issu de U76 est explicité pour éviter une double déduction des engagements ; aucune formule universelle ni adoption nouvelle.')
OUT['TER056'].setdefault('editorial_notes',[]).append('Inventory Ledger Management reste candidat non adopté ; la nouvelle source Amazon établit un usage documentaire du nom, sans décision de renommage.')
OUT['BHV035'].setdefault('editorial_notes',[]).append('Aucun document consulté ne démontre un moteur autonome couvrant tout Risk-Adaptive Reservation. Le texte distingue la convention FLOW des modes et contrôles documentés.')
for ident in ('TER041','TER042'):
    OUT[ident]['market_inspiration']['examples'][0]['source_refs'].insert(0,'U76')

assert len(OUT)==70
assert set(OUT)==set(original_by_id), (set(original_by_id)-set(OUT),set(OUT)-set(original_by_id))
errors=[]
for ident,record in OUT.items():
    comps=record['market_comparisons']; profile=record['market_inspiration']
    errors.extend(validate_comparisons(comps,ident))
    errors.extend(validate_inspiration(profile,comps,ident))
    if len({document_key(c['source_url']) for c in comps})<2:
        errors.append(ident+': fewer than two distinct documents')
    if not 2<=len(profile['synthesis'])<=3:
        errors.append(ident+': expected two or three synthesis paragraphs')
    for c in comps:
        if 'U477' not in c['source_refs']:
            errors.append(ident+': missing U477 provenance')
    for ex in profile['examples']:
        if not all(ex.get(k) for k in ('title','situation','outcome','lesson','source_title','source_url','source_refs')):
            errors.append(ident+': incomplete example')
if errors:
    raise ValueError('\n'.join(errors))

used={document_key(c['source_url']) for r in OUT.values() for c in r['market_comparisons']}
used.update(document_key(ex['source_url']) for r in OUT.values() for ex in r['market_inspiration']['examples'])
source_records=[]
for key,s in S.items():
    urlkey=document_key(s['source_url'])
    if urlkey not in used:
        continue
    refs=list(dict.fromkeys(r for old in prior_review if document_key(old['previous_comparison']['source_url'])==urlkey for r in old['previous_comparison']['source_refs']))
    supported=[ident for ident,r in OUT.items() if any(document_key(c['source_url'])==urlkey for c in r['market_comparisons']) or any(document_key(ex['source_url'])==urlkey for ex in r['market_inspiration']['examples'])]
    source_records.append(dict(local_key=key,**s,existing_source_refs=refs,supported_ids=supported,examples=EXAMPLES.get(key,[])))

output={'source':'U477','nodes':[OUT[x['id']] for x in original['nodes']],'terms':[OUT[x['id']] for x in original['terms']]}
evidence=dict(source='U477',batch='inventory',consulted_on='2026-09-19',
    scope={'nodes':44,'terms':26,'comparisons':sum(len(r['market_comparisons']) for r in OUT.values()),'primary_documents_used':len(source_records),'examples':70},
    method='Rédaction individuelle après lecture des fiches et passages primaires. Deux documents distincts minimum par fiche ; aucun nouveau nom, périmètre, accord ou modèle autoritaire. Exemples construits marqués Illustration FLOW ; les exemples éditeur et le cas client restent attribués.',
    consulted_primary_sources=source_records,prior_reference_review=prior_review,
    constraints=['Les pages SAP Help sans extraction et les pages IBM inaccessibles ne sont pas présentées comme fraîchement lues.', 'La vidéo Logility n’a pas été visionnée ; seul le texte de présentation a été examiné.', 'Le résumé primaire Achkar et al. a été lu, pas le développement algorithmique du papier.', 'Les termes et verbes locaux sont comparés à des usages proches ; aucune norme lexicale ni preuve de déploiement Beaumanoir n’est déduite.', 'Les références et propositions ajoutées restent proposées ; le lot ne modifie aucune adoption de champs.'],
    targeted_validation={'id_set':'70/70, equal to inventory-input.yaml','comparisons_contract':'passed','inspiration_contract':'passed','two_distinct_documents_per_record':'passed','two_or_three_synthesis_paragraphs':'passed','complete_examples':'70/70'})
(DIR/'inventory-output.yaml').write_text(dumps(output),encoding='utf-8')
(DIR/'inventory-sources.yaml').write_text(dumps(evidence),encoding='utf-8')
print(f"Inventory U477: {len(output['nodes'])} nodes, {len(output['terms'])} terms, {evidence['scope']['comparisons']} comparisons, {len(source_records)} documents, 70 examples; contracts and IDs passed.")
